:root {
  --ink: #f7f2e8;
  --night: #080d1e;
  --night-2: #101a38;
  --gold: #ffd34d;
  --red: #e33127;
  --controls-h: 0px;
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: var(--night);
  color: var(--ink);
  font-family: "Trebuchet MS", "Segoe UI", system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

body {
  background:
    radial-gradient(120% 90% at 50% 0%, #16224a 0%, #0b1229 45%, #060a17 100%);
}

#app {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

#stage-wrap {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(6px + var(--safe-t)) calc(6px + var(--safe-r)) 6px calc(6px + var(--safe-l));
}

#stage {
  position: relative;
  width: min(100%, calc((100dvh - var(--controls-h)) * 16 / 9));
  aspect-ratio: 16 / 9;
  max-height: 100%;
  border-radius: 14px;
  overflow: hidden;
  background: #5c94fc;
  box-shadow:
    0 0 0 2px rgba(255, 255, 255, 0.08),
    0 0 0 6px rgba(8, 12, 28, 0.55),
    0 26px 70px rgba(0, 0, 0, 0.55),
    0 0 90px rgba(58, 120, 255, 0.16);
}

#game {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  touch-action: none;
  cursor: default;
}

/* ---------- tiny stage buttons ---------- */

#stage-buttons {
  position: absolute;
  top: 8px;
  right: 8px;
  display: flex;
  gap: 6px;
  z-index: 5;
}

.icon-btn {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 9px;
  background: rgba(9, 16, 36, 0.42);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  color: #fff;
  cursor: pointer;
  transition: background 140ms ease, transform 140ms ease, opacity 140ms ease;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

.icon-btn svg {
  width: 17px;
  height: 17px;
  fill: currentColor;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.icon-btn svg path.wave { fill: none; }
.icon-btn:hover { background: rgba(30, 46, 92, 0.75); }
.icon-btn:active { transform: scale(0.92); }
.icon-btn.muted { opacity: 0.55; }
.icon-btn.muted .wave { opacity: 0; }

/* ---------- overlay ---------- */

.overlay {
  position: absolute;
  inset: 0;
  z-index: 4;
  display: grid;
  place-items: center;
  padding: 14px;
  background:
    radial-gradient(80% 80% at 50% 38%, rgba(6, 10, 24, 0.18), rgba(6, 10, 24, 0.62) 70%, rgba(6, 10, 24, 0.82) 100%);
  opacity: 0;
  visibility: hidden;
  transition: opacity 220ms ease, visibility 220ms;
}

.overlay.show {
  opacity: 1;
  visibility: visible;
}

.panel {
  width: min(94%, 560px);
  padding: clamp(12px, 2.4vw, 26px) clamp(14px, 3vw, 34px) clamp(12px, 2.2vw, 22px);
  text-align: center;
  border-radius: 20px;
  background: linear-gradient(180deg, rgba(21, 32, 66, 0.78), rgba(9, 14, 32, 0.86));
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12), 0 24px 60px rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  animation: panelIn 420ms cubic-bezier(0.2, 0.9, 0.3, 1.15) both;
}

@keyframes panelIn {
  from { transform: translateY(14px) scale(0.97); opacity: 0; }
  to { transform: translateY(0) scale(1); opacity: 1; }
}

.eyebrow {
  margin: 0 0 4px;
  font-size: clamp(9px, 1.6vw, 12px);
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: #9db6ff;
  font-weight: 700;
}

.logo {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin: 0;
  line-height: 0.86;
  font-weight: 900;
  text-transform: uppercase;
}

.logo .super {
  font-size: clamp(16px, 3.6vw, 30px);
  letter-spacing: 0.22em;
  color: var(--gold);
  text-shadow: 0 2px 0 #a4660a, 0 4px 10px rgba(0, 0, 0, 0.5);
}

.logo .mario {
  margin-top: 2px;
  font-size: clamp(42px, 10.5vw, 86px);
  letter-spacing: 0.02em;
  color: #ff3a2e;
  -webkit-text-stroke: clamp(1.5px, 0.45vw, 4px) #7d100b;
  paint-order: stroke fill;
  text-shadow:
    0 3px 0 #b51a12,
    0 7px 0 #7d100b,
    0 12px 22px rgba(0, 0, 0, 0.55);
}

.sub {
  margin: clamp(6px, 1.2vw, 12px) 0 clamp(10px, 2vw, 18px);
  font-size: clamp(10px, 1.7vw, 14px);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #cfd9f5;
  font-weight: 700;
}

.btn {
  position: relative;
  display: inline-block;
  padding: clamp(9px, 1.5vw, 13px) clamp(22px, 4vw, 40px);
  border: 0;
  border-radius: 12px;
  font-family: inherit;
  font-size: clamp(14px, 2.2vw, 19px);
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #fff8ec;
  background: linear-gradient(180deg, #ff6b52 0%, #e33127 55%, #bd1e16 100%);
  box-shadow:
    inset 0 2px 0 rgba(255, 255, 255, 0.45),
    inset 0 -3px 0 rgba(0, 0, 0, 0.25),
    0 5px 0 #7d100b,
    0 12px 26px rgba(227, 49, 39, 0.4);
  cursor: pointer;
  transition: transform 100ms ease, box-shadow 100ms ease, filter 160ms ease;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

.btn:hover { filter: brightness(1.08); }
.btn:active {
  transform: translateY(4px);
  box-shadow:
    inset 0 2px 0 rgba(255, 255, 255, 0.35),
    inset 0 -2px 0 rgba(0, 0, 0, 0.25),
    0 1px 0 #7d100b,
    0 5px 12px rgba(227, 49, 39, 0.35);
}
.btn:focus-visible { outline: 3px solid #ffe9a3; outline-offset: 3px; }

.keys {
  margin: clamp(8px, 1.8vw, 16px) 0 0;
  font-size: clamp(9px, 1.5vw, 12px);
  letter-spacing: 0.06em;
  color: #9fb0d8;
  font-weight: 600;
}

.touchhint { display: none; }

/* ---------- touch controls ---------- */

#touch {
  display: none;
  flex: 0 0 auto;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  padding: 6px calc(16px + var(--safe-r)) calc(14px + var(--safe-b)) calc(16px + var(--safe-l));
  height: var(--controls-h);
  min-height: 0;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}

.pad {
  display: flex;
  align-items: center;
  gap: 10px;
}

.pad-right { align-items: flex-end; }

.tbtn {
  width: clamp(54px, 15vw, 78px);
  height: clamp(54px, 15vw, 78px);
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.26);
  border-radius: 50%;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.17), rgba(255, 255, 255, 0.06));
  box-shadow:
    inset 0 2px 0 rgba(255, 255, 255, 0.28),
    inset 0 -6px 12px rgba(0, 0, 0, 0.25),
    0 8px 20px rgba(0, 0, 0, 0.35);
  color: #fff;
  font-family: inherit;
  font-weight: 900;
  font-size: clamp(18px, 5vw, 26px);
  cursor: pointer;
  touch-action: none;
  -webkit-tap-highlight-color: transparent;
  transition: transform 70ms ease, background 90ms ease;
}

.tbtn svg { width: 45%; height: 45%; fill: currentColor; }
.tbtn.pressed, .tbtn:active {
  transform: scale(0.93);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.3), rgba(255, 255, 255, 0.12));
}

.tbtn-jump {
  width: clamp(64px, 17vw, 92px);
  height: clamp(64px, 17vw, 92px);
  background: linear-gradient(180deg, rgba(255, 116, 96, 0.95), rgba(200, 32, 24, 0.95));
  border-color: rgba(255, 214, 200, 0.6);
  box-shadow:
    inset 0 3px 0 rgba(255, 255, 255, 0.4),
    inset 0 -7px 14px rgba(0, 0, 0, 0.28),
    0 10px 24px rgba(227, 49, 39, 0.42);
}

.tbtn-run {
  background: linear-gradient(180deg, rgba(255, 216, 90, 0.95), rgba(214, 152, 18, 0.95));
  border-color: rgba(255, 246, 200, 0.65);
  color: #4a2a00;
  box-shadow:
    inset 0 3px 0 rgba(255, 255, 255, 0.5),
    inset 0 -7px 14px rgba(0, 0, 0, 0.22),
    0 10px 24px rgba(214, 152, 18, 0.35);
}

/* Show controls on touch-first devices and narrow screens */
@media (pointer: coarse), (max-width: 860px) {
  :root { --controls-h: clamp(132px, 25dvh, 210px); }
  #touch { display: flex; }
  .desk { display: none; }
  .touchhint { display: inline; }
}

/* Landscape phones: float the controls over the game instead of stealing height */
@media (orientation: landscape) and (max-height: 560px) {
  :root { --controls-h: 0px; }
  #touch {
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    height: auto;
    padding: 0 calc(18px + var(--safe-r)) calc(12px + var(--safe-b)) calc(18px + var(--safe-l));
    pointer-events: none;
    z-index: 6;
  }
  #touch .pad { pointer-events: auto; }
  .tbtn {
    width: 62px;
    height: 62px;
    background: linear-gradient(180deg, rgba(12, 20, 42, 0.5), rgba(12, 20, 42, 0.3));
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
  }
  .tbtn-jump {
    width: 72px;
    height: 72px;
    background: linear-gradient(180deg, rgba(255, 116, 96, 0.9), rgba(200, 32, 24, 0.9));
  }
  .tbtn-run {
    background: linear-gradient(180deg, rgba(255, 216, 90, 0.9), rgba(214, 152, 18, 0.9));
  }
  .panel { transform: scale(0.92); }
}

@media (max-width: 420px) {
  #stage { border-radius: 10px; }
  #stage-wrap { padding-left: 4px; padding-right: 4px; }
  .icon-btn { width: 26px; height: 26px; border-radius: 7px; }
  .icon-btn svg { width: 14px; height: 14px; }
  #stage-buttons { top: 5px; right: 5px; gap: 4px; }
}

@media (prefers-reduced-motion: reduce) {
  .panel { animation: none; }
  .btn, .icon-btn, .tbtn { transition: none; }
}

// Tiny WebAudio chiptune engine: generated sound effects plus a looping
// original melody, so the game ships without any audio files.
const SEMITONE = { C: 0, 'C#': 1, D: 2, 'D#': 3, E: 4, F: 5, 'F#': 6, G: 7, 'G#': 8, A: 9, 'A#': 10, B: 11 };

function noteToFreq(name) {
  const match = /^([A-G]#?)(-?\d)$/.exec(name);
  if (!match) return 0;
  const midi = (Number(match[2]) + 1) * 12 + SEMITONE[match[1]];
  return 440 * Math.pow(2, (midi - 69) / 12);
}

const MELODY = [
  'G4', 'B4', 'D5', 'B4', 'G4', 'A4', 'B4', null,
  'A4', 'C5', 'E5', 'C5', 'A4', 'G4', 'A4', null,
  'B4', 'D5', 'G5', 'D5', 'B4', 'A4', 'G4', null,
  'E4', 'G4', 'A4', 'B4', 'D5', 'B4', 'G4', null,
];
const BASS = ['G2', 'G2', 'A2', 'A2', 'B2', 'B2', 'E2', 'E2', 'G2', 'G2', 'D2', 'D2', 'E2', 'E2', 'G2', 'D2'];

export class Sound {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.musicOn = false;
    this.step = 0;
    this.nextTime = 0;
    this.timer = null;
    this.stepDur = 0.2; // eighth notes at 150 bpm
  }

  ensure() {
    if (!this.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.32;
      this.master.connect(this.ctx.destination);
    }
    if (this.ctx.state === 'suspended') this.ctx.resume();
    return this.ctx;
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.setTargetAtTime(muted ? 0 : 0.32, this.ctx.currentTime, 0.02);
    }
  }

  tone(freq, duration, { type = 'square', volume = 0.3, slide = 0, delay = 0, attack = 0.005 } = {}) {
    const ctx = this.ctx;
    if (!ctx) return;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, freq), t0);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t0 + duration);
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.linearRampToValueAtTime(volume, t0 + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    osc.connect(gain).connect(this.master);
    osc.start(t0);
    osc.stop(t0 + duration + 0.02);
  }

  noise(duration, { volume = 0.2, delay = 0, freq = 1200 } = {}) {
    const ctx = this.ctx;
    if (!ctx) return;
    const t0 = ctx.currentTime + delay;
    const length = Math.max(1, Math.floor(ctx.sampleRate * duration));
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / length);
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = freq;
    filter.Q.value = 0.8;
    const gain = ctx.createGain();
    gain.gain.value = volume;
    source.connect(filter).connect(gain).connect(this.master);
    source.start(t0);
  }

  jump() { this.tone(330, 0.16, { type: 'square', volume: 0.22, slide: 480 }); }
  bigJump() { this.tone(280, 0.2, { type: 'square', volume: 0.24, slide: 560 }); }
  coin() {
    this.tone(noteToFreq('B5'), 0.09, { type: 'square', volume: 0.2 });
    this.tone(noteToFreq('E6'), 0.26, { type: 'square', volume: 0.2, delay: 0.07 });
  }
  bump() { this.tone(150, 0.1, { type: 'square', volume: 0.18, slide: -60 }); }
  brick() { this.noise(0.18, { volume: 0.26, freq: 900 }); this.tone(110, 0.14, { type: 'square', volume: 0.14, slide: -50 }); }
  stomp() { this.tone(200, 0.12, { type: 'square', volume: 0.22, slide: -110 }); this.noise(0.09, { volume: 0.16, freq: 500 }); }
  kick() { this.tone(420, 0.1, { type: 'square', volume: 0.18, slide: -220 }); }
  power() {
    const notes = ['C5', 'E5', 'G5', 'C6', 'E6', 'G6'];
    notes.forEach((n, i) => this.tone(noteToFreq(n), 0.14, { type: 'square', volume: 0.2, delay: i * 0.055 }));
  }
  grow() {
    const notes = ['C4', 'E4', 'G4', 'C5', 'E5', 'G5', 'C6'];
    notes.forEach((n, i) => this.tone(noteToFreq(n), 0.1, { type: 'triangle', volume: 0.22, delay: i * 0.045 }));
  }
  fire() { this.tone(700, 0.09, { type: 'sawtooth', volume: 0.14, slide: -420 }); }
  hurt() { this.tone(340, 0.32, { type: 'square', volume: 0.22, slide: -260 }); }
  die() {
    this.stopMusic();
    const notes = ['B4', 'F4', 'D4', 'B3', 'G3', 'E3', 'C3'];
    notes.forEach((n, i) => this.tone(noteToFreq(n), 0.24, { type: 'square', volume: 0.22, delay: i * 0.11 }));
  }
  flag() {
    this.stopMusic();
    const notes = ['C5', 'E5', 'G5', 'C6', 'G5', 'C6'];
    notes.forEach((n, i) => this.tone(noteToFreq(n), 0.2, { type: 'square', volume: 0.2, delay: i * 0.1 }));
  }
  clear() {
    const notes = ['C5', 'C5', 'C5', 'C5', 'G4', 'A4', 'C5', 'A4', 'C5', 'E5'];
    notes.forEach((n, i) => this.tone(noteToFreq(n), 0.26, { type: 'square', volume: 0.2, delay: i * 0.14 }));
  }
  tick() { this.tone(1200, 0.04, { type: 'square', volume: 0.08 }); }

  startMusic() {
    if (!this.ensure() || this.musicOn) return;
    this.musicOn = true;
    this.step = 0;
    this.nextTime = this.ctx.currentTime + 0.08;
    this.timer = setInterval(() => this.schedule(), 40);
  }

  stopMusic() {
    this.musicOn = false;
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
  }

  schedule() {
    if (!this.ctx || !this.musicOn) return;
    const horizon = this.ctx.currentTime + 0.18;
    while (this.nextTime < horizon) {
      const i = this.step % MELODY.length;
      const note = MELODY[i];
      const delay = Math.max(0, this.nextTime - this.ctx.currentTime);
      if (note) {
        this.tone(noteToFreq(note), this.stepDur * 0.86, { type: 'square', volume: 0.11, delay });
      }
      if (i % 2 === 0) {
        const bass = BASS[(this.step >> 1) % BASS.length];
        this.tone(noteToFreq(bass), this.stepDur * 1.7, { type: 'triangle', volume: 0.13, delay });
      }
      if (i % 4 === 2) this.noise(0.05, { volume: 0.035, freq: 6000, delay });
      this.step++;
      this.nextTime += this.stepDur;
    }
  }
}

export const TILE = 16;

export const T = {
  EMPTY: 0,
  GROUND: 1,
  BRICK: 2,
  QCOIN: 3,
  QPOWER: 4,
  USED: 5,
  STONE: 6,
  PIPE: 7,
};

const GROUND_TOP = 13;

function makeRng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

export function buildLevel() {
  const W = 216;
  const H = 15;
  const tiles = new Uint8Array(W * H);
  const solid = new Uint8Array(W * H);
  const rng = makeRng(1337);

  const set = (x, y, type, isSolid = true) => {
    if (x < 0 || x >= W || y < 0 || y >= H) return;
    const i = y * W + x;
    tiles[i] = type;
    solid[i] = isSolid ? 1 : 0;
  };

  const ground = (x0, x1, top = GROUND_TOP) => {
    for (let x = x0; x <= x1; x++) {
      for (let y = top; y < H; y++) set(x, y, T.GROUND);
    }
  };

  const row = (x0, x1, y, type) => {
    for (let x = x0; x <= x1; x++) set(x, y, type);
  };

  // ---- terrain -------------------------------------------------------
  ground(0, 68);
  ground(71, 85);
  ground(89, 152);
  ground(155, 215);

  // ---- blocks --------------------------------------------------------
  set(16, 9, T.QCOIN);

  set(20, 9, T.BRICK);
  set(21, 9, T.QCOIN);
  set(22, 9, T.BRICK);
  set(23, 9, T.QPOWER);
  set(24, 9, T.BRICK);

  row(22, 26, 5, T.BRICK);
  set(24, 5, T.QCOIN);

  set(33, 9, T.BRICK);
  set(34, 9, T.QCOIN);
  set(35, 9, T.BRICK);

  set(44, 9, T.QCOIN);

  set(53, 9, T.QCOIN);

  set(63, 9, T.BRICK);
  set(64, 9, T.QCOIN);
  set(65, 9, T.BRICK);

  set(78, 9, T.QCOIN);

  set(92, 9, T.QPOWER);
  set(93, 9, T.BRICK);

  set(100, 9, T.BRICK);
  set(101, 9, T.QCOIN);
  set(102, 9, T.BRICK);
  row(100, 102, 5, T.BRICK);

  set(112, 9, T.QCOIN);
  set(113, 9, T.BRICK);
  set(114, 9, T.QCOIN);

  row(124, 128, 9, T.BRICK);
  set(126, 9, T.QPOWER);

  set(135, 9, T.QCOIN);

  set(145, 9, T.BRICK);
  set(146, 9, T.QCOIN);
  set(147, 9, T.BRICK);

  set(160, 9, T.QCOIN);

  set(170, 9, T.QCOIN);
  set(171, 9, T.BRICK);
  set(172, 9, T.QCOIN);

  row(176, 180, 9, T.BRICK);
  set(178, 9, T.QCOIN);

  // staircase before the flag
  for (let i = 0; i < 8; i++) {
    for (let y = GROUND_TOP - 1 - i; y < GROUND_TOP; y++) set(182 + i, y, T.STONE);
  }

  // ---- pipes ---------------------------------------------------------
  const pipes = [];
  const addPipe = (x, height, plant = false) => {
    pipes.push({ x: x * TILE, y: (GROUND_TOP - height) * TILE, w: TILE * 2, h: height * TILE, plant });
    for (let tx = x; tx < x + 2; tx++) {
      for (let ty = GROUND_TOP - height; ty < GROUND_TOP; ty++) set(tx, ty, T.PIPE);
    }
  };
  addPipe(28, 2);
  addPipe(38, 3, true);
  addPipe(46, 4);
  addPipe(57, 4, true);
  addPipe(168, 2);

  // ---- coins ---------------------------------------------------------
  const coins = [];
  const coin = (tx, ty) => coins.push({ x: tx * TILE + TILE / 2, y: ty * TILE + TILE / 2 });

  // arcs over the gaps
  coin(69, 10); coin(70, 9); coin(71, 10);
  coin(86, 10); coin(87, 9); coin(88, 10);
  coin(153, 10); coin(154, 10);

  // floating rows
  for (let x = 51; x <= 54; x++) coin(x, 7);
  for (let x = 105; x <= 108; x++) coin(x, 7);
  for (let x = 130; x <= 133; x++) coin(x, 7);
  for (let x = 191; x <= 195; x++) coin(x, 7);
  coin(183, 3); coin(184, 2); coin(185, 3);

  // ---- enemies -------------------------------------------------------
  const enemies = [];
  const goomba = (tx, ty = GROUND_TOP - 1) => enemies.push({ type: 'goomba', tx, ty });
  const koopa = (tx, ty = GROUND_TOP - 1) => enemies.push({ type: 'koopa', tx, ty });

  goomba(22); goomba(41); goomba(52); goomba(53);
  goomba(79); goomba(96); goomba(97);
  goomba(118); goomba(119);
  goomba(138); goomba(161); goomba(174);
  koopa(63); koopa(108); koopa(144);
  goomba(187);

  // ---- decorations ---------------------------------------------------
  const hills = [];
  const bushes = [];
  const clouds = [];

  for (let x = -4; x < W + 10; x += 7 + Math.floor(rng() * 7)) {
    const size = 1 + Math.floor(rng() * 2);
    if (rng() < 0.62) hills.push({ x: x * TILE, size });
    if (rng() < 0.55) bushes.push({ x: x * TILE + rng() * 40, size: 1 + Math.floor(rng() * 2) });
  }
  for (let x = -2; x < W + 8; x += 9 + Math.floor(rng() * 10)) {
    clouds.push({ x: x * TILE, y: 22 + rng() * 58, size: 1 + Math.floor(rng() * 2), speed: 2 + rng() * 4 });
  }

  const flagX = 198 * TILE + 8;
  const castleX = 203 * TILE;

  return {
    W, H, tiles, solid, pipes, coins, enemies, hills, bushes, clouds,
    groundTop: GROUND_TOP * TILE,
    flagX,
    castleX,
    width: W * TILE,
    height: H * TILE,
    spawn: { x: 3 * TILE, y: (GROUND_TOP - 1) * TILE },
  };
}

// Hand-drawn pixel sprites. Everything is composed from small rectangles so the
// art stays crisp at any scale and the whole game ships without image assets.

const SKIN = '#ffc39b';
const SKIN_DARK = '#e09a70';
const HAIR = '#5a2c10';
const DARK = '#241407';
const SHOE = '#6b3a1a';
const WHITE = '#fff6e8';

function px(ctx, x, y, w, h, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x, y, w, h);
}

function marioPalette(power) {
  if (power === 2) {
    return { cap: '#f7f3e6', capDark: '#cfc6ae', shirt: '#f7f3e6', overall: '#e33127', overallDark: '#a81f1a' };
  }
  return { cap: '#e33127', capDark: '#a81f1a', shirt: '#e33127', overall: '#2f5fd0', overallDark: '#1d3f96' };
}

export function drawMario(ctx, x, y, w, h, o) {
  const scale = o.power > 0 ? 1.78 : 1;
  const spriteW = 12 * scale;
  const spriteH = 16 * scale;
  const ax = Math.round(x + w / 2 - spriteW / 2);
  const ay = Math.round(y + h - spriteH);
  const pal = marioPalette(o.power);
  const facing = o.facing < 0 ? -1 : 1;

  ctx.save();
  ctx.translate(ax + (facing < 0 ? spriteW : 0), ay);
  ctx.scale(facing < 0 ? -scale : scale, scale);

  const walking = o.onGround && Math.abs(o.vx) > 6 && !o.skid && !o.dead;
  const swing = walking ? Math.sin(o.walkPhase * Math.PI * 2) : 0;
  const bounce = walking ? (Math.abs(swing) > 0.7 ? -1 : 0) : 0;

  // --- legs & shoes -------------------------------------------------
  let frontLegX = 3;
  let backLegX = 7;
  let frontShoeX = 2;
  let backShoeX = 7;
  let frontShoeY = 14;
  let backShoeY = 14;

  if (o.dead) {
    frontLegX = 3; backLegX = 7;
    frontShoeX = 2; backShoeX = 7;
  } else if (!o.onGround) {
    frontLegX = 4; backLegX = 7;
    frontShoeX = 4; frontShoeY = 13;
    backShoeX = 8; backShoeY = 15;
  } else if (o.skid) {
    frontShoeX = 1; backShoeX = 8;
  } else if (walking) {
    frontLegX = 3 + Math.round(swing * 1.4);
    backLegX = 7 + Math.round(swing * 1.4);
    frontShoeX = 2 + Math.round(swing * 2);
    backShoeX = 7 + Math.round(swing * 2);
    frontShoeY = 14 + (swing > 0.75 ? -1 : 0);
  }

  px(ctx, frontLegX, 12 + bounce, 2, 2, pal.overallDark);
  px(ctx, backLegX, 12 + bounce, 2, 2, pal.overallDark);
  px(ctx, frontShoeX, frontShoeY + bounce, 4, 2, SHOE);
  px(ctx, backShoeX, backShoeY + bounce, 4, 2, SHOE);
  px(ctx, frontShoeX, frontShoeY + 1 + bounce, 4, 1, '#3f210e');
  px(ctx, backShoeX, backShoeY + 1 + bounce, 4, 1, '#3f210e');

  // --- torso ---------------------------------------------------------
  const bodyY = bounce;
  px(ctx, 3, 9 + bodyY, 7, 3, pal.overall);
  px(ctx, 3, 11 + bodyY, 7, 1, pal.overallDark);
  px(ctx, 3, 7 + bodyY, 7, 2, pal.shirt);
  px(ctx, 4, 7 + bodyY, 2, 2, pal.overall);
  px(ctx, 7, 7 + bodyY, 2, 2, pal.overall);
  px(ctx, 4, 9 + bodyY, 1, 1, '#ffd94a');
  px(ctx, 8, 9 + bodyY, 1, 1, '#ffd94a');

  // --- arms ----------------------------------------------------------
  if (o.dead) {
    px(ctx, 1, 6 + bodyY, 2, 3, pal.shirt);
    px(ctx, 9, 6 + bodyY, 2, 3, pal.shirt);
    px(ctx, 1, 4 + bodyY, 2, 2, SKIN);
    px(ctx, 9, 4 + bodyY, 2, 2, SKIN);
  } else if (!o.onGround) {
    px(ctx, 1, 7 + bodyY, 2, 3, pal.shirt);
    px(ctx, 9, 5 + bodyY, 2, 4, pal.shirt);
    px(ctx, 1, 9 + bodyY, 2, 2, SKIN);
    px(ctx, 9, 4 + bodyY, 2, 2, SKIN);
  } else if (o.skid) {
    px(ctx, 1, 7 + bodyY, 2, 3, pal.shirt);
    px(ctx, 9, 8 + bodyY, 2, 2, pal.shirt);
    px(ctx, 1, 10 + bodyY, 2, 1, SKIN);
    px(ctx, 10, 8 + bodyY, 2, 2, SKIN);
  } else if (walking) {
    px(ctx, 1, 8 + bodyY + Math.round(swing), 2, 3, pal.shirt);
    px(ctx, 9, 8 + bodyY - Math.round(swing), 2, 3, pal.shirt);
    px(ctx, 1, 11 + bodyY + Math.round(swing), 2, 1, SKIN);
    px(ctx, 9, 11 + bodyY - Math.round(swing), 2, 1, SKIN);
  } else {
    px(ctx, 2, 8 + bodyY, 1, 3, pal.shirt);
    px(ctx, 9, 8 + bodyY, 2, 3, pal.shirt);
    px(ctx, 2, 10 + bodyY, 1, 1, SKIN);
    px(ctx, 10, 10 + bodyY, 1, 1, SKIN);
  }

  // --- head ----------------------------------------------------------
  const headY = bodyY;
  px(ctx, 2, 0 + headY, 8, 2, pal.cap);
  px(ctx, 1, 2 + headY, 10, 1, pal.cap);
  px(ctx, 1, 2 + headY, 10, 1, pal.capDark);
  px(ctx, 2, 0 + headY, 8, 1, pal.cap);
  px(ctx, 3, 0 + headY, 4, 1, '#ff6f5e');

  px(ctx, 2, 3 + headY, 2, 3, HAIR);
  px(ctx, 4, 3 + headY, 6, 3, SKIN);
  px(ctx, 4, 3 + headY, 6, 1, SKIN_DARK);
  px(ctx, 7, 4 + headY, 1, 2, DARK);
  px(ctx, 8, 3 + headY, 1, 1, SKIN_DARK);
  px(ctx, 9, 5 + headY, 2, 2, SKIN);
  px(ctx, 10, 6 + headY, 1, 1, SKIN_DARK);
  px(ctx, 5, 6 + headY, 4, 1, HAIR);
  px(ctx, 4, 6 + headY, 1, 1, HAIR);
  px(ctx, 5, 7 + headY, 4, 1, SKIN_DARK);
  px(ctx, 3, 5 + headY, 1, 2, SKIN_DARK);

  // a tiny sparkle when invincible / powered up
  if (o.glow) {
    ctx.globalAlpha = 0.55;
    px(ctx, 0, 1 + headY, 1, 1, WHITE);
    px(ctx, 11, 3 + headY, 1, 1, WHITE);
    ctx.globalAlpha = 1;
  }

  ctx.restore();
}

export function drawGoomba(ctx, x, y, w, h, o) {
  const facing = o.vx < 0 ? -1 : 1;
  ctx.save();
  ctx.translate(Math.round(x + w / 2), Math.round(y + h));
  ctx.scale(facing, 1);

  if (o.state === 'squash') {
    px(ctx, -7, -5, 14, 5, '#8b4a1f');
    px(ctx, -7, -5, 14, 1, '#a9622c');
    px(ctx, -6, -2, 3, 2, '#3a1f0c');
    px(ctx, 3, -2, 3, 2, '#3a1f0c');
    ctx.restore();
    return;
  }

  const step = Math.floor(o.anim * 8) % 2;
  // feet
  px(ctx, -7 + step, -3, 6, 3, '#3a1f0c');
  px(ctx, 1 - step, -3, 6, 3, '#3a1f0c');
  // body
  px(ctx, -6, -12, 12, 9, '#8b4a1f');
  px(ctx, -7, -9, 14, 6, '#8b4a1f');
  px(ctx, -5, -13, 10, 2, '#a9622c');
  px(ctx, -6, -12, 12, 1, '#a9622c');
  px(ctx, -5, -4, 10, 1, '#6d3615');
  // eyes
  px(ctx, -5, -10, 4, 4, WHITE);
  px(ctx, 1, -10, 4, 4, WHITE);
  px(ctx, -2, -9, 2, 3, DARK);
  px(ctx, 2, -9, 2, 3, DARK);
  // angry brows
  px(ctx, -6, -12, 4, 1, '#4a250e');
  px(ctx, 2, -12, 4, 1, '#4a250e');
  px(ctx, -5, -11, 2, 1, '#4a250e');
  px(ctx, 3, -11, 2, 1, '#4a250e');
  // mouth
  px(ctx, -2, -6, 4, 1, '#4a250e');
  ctx.restore();
}

export function drawKoopa(ctx, x, y, w, h, o) {
  const facing = o.facing || 1;
  ctx.save();
  ctx.translate(Math.round(x + w / 2), Math.round(y + h));
  ctx.scale(facing, 1);

  if (o.state === 'shell') {
    px(ctx, -7, -12, 14, 10, '#2e9e3e');
    px(ctx, -7, -12, 14, 2, '#4dc45d');
    px(ctx, -8, -5, 16, 5, '#f0e2a2');
    px(ctx, -8, -5, 16, 1, '#c9b56f');
    px(ctx, -5, -10, 4, 4, '#1d6f2b');
    px(ctx, 1, -10, 4, 4, '#1d6f2b');
    px(ctx, -2, -8, 4, 4, '#1d6f2b');
    if (o.spin) {
      px(ctx, -8, -13, 2, 2, WHITE);
      px(ctx, 6, -13, 2, 2, WHITE);
    }
    ctx.restore();
    return;
  }

  const step = Math.floor(o.anim * 7) % 2;
  // feet
  px(ctx, -6 + step, -3, 5, 3, '#f2a03a');
  px(ctx, 1 - step, -3, 5, 3, '#f2a03a');
  // shell
  px(ctx, -7, -14, 14, 11, '#2e9e3e');
  px(ctx, -6, -15, 12, 2, '#4dc45d');
  px(ctx, -8, -6, 16, 4, '#f0e2a2');
  px(ctx, -8, -6, 16, 1, '#c9b56f');
  px(ctx, -4, -12, 4, 4, '#1d6f2b');
  px(ctx, 2, -12, 3, 3, '#1d6f2b');
  px(ctx, -1, -9, 4, 3, '#1d6f2b');
  // head
  px(ctx, 4, -19, 5, 6, '#f7e08a');
  px(ctx, 4, -19, 5, 1, '#fff2b8');
  px(ctx, 8, -18, 3, 4, '#f7e08a');
  px(ctx, 8, -17, 1, 2, DARK);
  px(ctx, 9, -14, 2, 1, '#c9a54a');
  // neck
  px(ctx, 2, -16, 4, 4, '#f7e08a');
  ctx.restore();
}

export function drawMushroom(ctx, x, y, w, h, o = {}) {
  const bob = o.bob ? Math.sin(o.bob * 6) * 0.5 : 0;
  ctx.save();
  ctx.translate(Math.round(x + w / 2), Math.round(y + h + bob));
  px(ctx, -6, -6, 12, 6, '#ffe9c9');
  px(ctx, -6, -6, 12, 1, '#fff8ec');
  px(ctx, -5, -4, 2, 2, DARK);
  px(ctx, 3, -4, 2, 2, DARK);
  px(ctx, -1, -2, 2, 1, '#d9b48c');
  // cap
  px(ctx, -7, -13, 14, 8, '#e33127');
  px(ctx, -6, -14, 12, 2, '#ff5a4a');
  px(ctx, -7, -13, 14, 1, '#b51a12');
  px(ctx, -5, -12, 3, 3, WHITE);
  px(ctx, 2, -12, 3, 3, WHITE);
  px(ctx, -2, -9, 4, 2, WHITE);
  ctx.restore();
}

export function drawFlower(ctx, x, y, w, h, t) {
  const sway = Math.sin(t * 3) * 0.7;
  ctx.save();
  ctx.translate(Math.round(x + w / 2), Math.round(y + h));
  // stem + leaves
  px(ctx, -1, -9, 2, 9, '#2e9e3e');
  px(ctx, -5, -6, 4, 2, '#4dc45d');
  px(ctx, 1, -4, 4, 2, '#4dc45d');
  // petals
  const petals = [
    [-5, -16], [1, -16], [-7, -12], [3, -12], [-3, -19], [-1, -8],
  ];
  for (const [px0, py0] of petals) px(ctx, px0 + sway, py0, 4, 4, '#ff8a2b');
  px(ctx, -4, -16, 4, 4, '#ffd94a');
  px(ctx, -5, -15, 2, 2, '#e33127');
  px(ctx, -3, -14, 1, 1, DARK);
  px(ctx, -1, -14, 1, 1, DARK);
  ctx.restore();
}

export function drawCoin(ctx, x, y, r, t) {
  const spin = Math.cos(t * 5);
  const sx = Math.max(0.18, Math.abs(spin));
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(sx, 1);
  ctx.beginPath();
  ctx.arc(0, 0, r, 0, Math.PI * 2);
  ctx.fillStyle = '#f2b33d';
  ctx.fill();
  ctx.beginPath();
  ctx.arc(0, 0, r - 1.5, 0, Math.PI * 2);
  ctx.fillStyle = '#ffd75e';
  ctx.fill();
  ctx.fillStyle = '#fff2b0';
  ctx.fillRect(-1, -r + 2.5, 2, r * 2 - 5);
  ctx.fillStyle = '#c9821f';
  ctx.fillRect(-r + 1, -r + 1, 1.5, r * 2 - 2);
  ctx.restore();
}

export function drawFireball(ctx, x, y, t) {
  const r = 4;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(t * 12);
  ctx.beginPath();
  ctx.arc(0, 0, r, 0, Math.PI * 2);
  ctx.fillStyle = '#ff7a1a';
  ctx.fill();
  ctx.beginPath();
  ctx.arc(0, 0, r - 1.6, 0, Math.PI * 2);
  ctx.fillStyle = '#ffe066';
  ctx.fill();
  ctx.fillStyle = '#fff6c9';
  ctx.fillRect(-1, -1, 2, 2);
  ctx.restore();
}

export function drawPiranha(ctx, x, y, h, t, open) {
  const mouth = open ? 3 : 1;
  ctx.save();
  ctx.translate(Math.round(x), Math.round(y));
  // stem
  px(ctx, -3, -h, 6, h, '#2e9e3e');
  px(ctx, -3, -h, 2, h, '#4dc45d');
  px(ctx, -5, -h * 0.55, 4, 3, '#4dc45d');
  px(ctx, 1, -h * 0.35, 4, 3, '#4dc45d');
  // head
  px(ctx, -7, -h - 10, 14, 8, '#e33127');
  px(ctx, -7, -h - 10, 14, 2, '#ff5a4a');
  px(ctx, -5, -h - 8, 3, 2, WHITE);
  px(ctx, 2, -h - 8, 3, 2, WHITE);
  px(ctx, -5, -h - 2, 10, mouth + 2, '#7d100b');
  for (let i = -4; i < 5; i += 3) px(ctx, i, -h - 2, 2, 2, WHITE);
  for (let i = -3; i < 4; i += 3) px(ctx, i, -h + mouth, 2, 1, WHITE);
  ctx.restore();
}

import { drawText, textWidth } from './font.js';
import * as S from './sprites.js';
import { TILE, T } from './level.js';

export const VIEW_W = 400;
export const VIEW_H = 225;

const C = {
  ground: '#c97a3c',
  groundLight: '#e8a35e',
  groundHi: '#f6c98f',
  groundDark: '#8a4a1c',
  groundShade: '#a75f28',
  brick: '#cf5a2e',
  brickHi: '#ef8a58',
  brickDark: '#7c2f12',
  stone: '#cbb894',
  stoneHi: '#e9dcbc',
  stoneDark: '#8f7a55',
  pipe: '#2fa84f',
  pipeHi: '#7fe08a',
  pipeDark: '#146b31',
};

function hash(x, y) {
  let h = (x * 374761393 + y * 668265263) | 0;
  h = (h ^ (h >>> 13)) * 1274126177;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

function drawSky(ctx, cam, t) {
  const g = ctx.createLinearGradient(0, 0, 0, VIEW_H);
  g.addColorStop(0, '#3d7ce4');
  g.addColorStop(0.45, '#63a3f2');
  g.addColorStop(0.8, '#a9d6ff');
  g.addColorStop(1, '#d8ecff');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, VIEW_W, VIEW_H);

  const sun = ctx.createRadialGradient(340, 38, 4, 340, 38, 130);
  sun.addColorStop(0, 'rgba(255, 248, 205, 0.85)');
  sun.addColorStop(0.35, 'rgba(255, 240, 170, 0.22)');
  sun.addColorStop(1, 'rgba(255, 240, 170, 0)');
  ctx.fillStyle = sun;
  ctx.fillRect(180, 0, 220, 200);

  // soft cloud haze near the horizon
  const haze = ctx.createLinearGradient(0, VIEW_H - 80, 0, VIEW_H);
  haze.addColorStop(0, 'rgba(255,255,255,0)');
  haze.addColorStop(1, 'rgba(255,255,255,0.35)');
  ctx.fillStyle = haze;
  ctx.fillRect(0, VIEW_H - 80, VIEW_W, 80);
}

function drawCloud(ctx, x, y, size) {
  const s = size;
  ctx.save();
  ctx.translate(Math.round(x), Math.round(y));
  ctx.fillStyle = 'rgba(190, 220, 255, 0.75)';
  const puffs = [
    [0, 6, 11 * s], [12 * s, 2, 14 * s], [26 * s, 7, 10 * s],
    [8 * s, 12, 12 * s], [20 * s, 13, 11 * s],
  ];
  for (const [px, py, r] of puffs) {
    ctx.beginPath();
    ctx.arc(px, py + 2, r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.fillStyle = '#ffffff';
  for (const [px, py, r] of puffs) {
    ctx.beginPath();
    ctx.arc(px, py, r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.fillStyle = 'rgba(255,255,255,0.95)';
  ctx.beginPath();
  ctx.arc(12 * s, 2, 12 * s, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function drawHill(ctx, x, groundY, size) {
  const w = 74 + size * 46;
  const h = 40 + size * 26;
  ctx.save();
  ctx.translate(Math.round(x), Math.round(groundY));
  ctx.fillStyle = '#3fae4f';
  ctx.beginPath();
  ctx.moveTo(-w / 2, 0);
  ctx.quadraticCurveTo(-w * 0.34, -h * 0.98, 0, -h);
  ctx.quadraticCurveTo(w * 0.34, -h * 0.98, w / 2, 0);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#2f8f3f';
  ctx.beginPath();
  ctx.moveTo(0, -h);
  ctx.quadraticCurveTo(w * 0.34, -h * 0.98, w / 2, 0);
  ctx.lineTo(w * 0.16, 0);
  ctx.quadraticCurveTo(w * 0.2, -h * 0.7, 0, -h);
  ctx.closePath();
  ctx.fill();
  // little face-like spots, a nod to the classic hills
  ctx.fillStyle = '#2a7f37';
  const spots = [[-w * 0.16, -h * 0.46], [w * 0.14, -h * 0.5], [-w * 0.02, -h * 0.72]];
  for (const [sx, sy] of spots) {
    ctx.beginPath();
    ctx.ellipse(sx, sy, 3.5, 5.5, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

function drawBush(ctx, x, groundY, size) {
  const s = size;
  ctx.save();
  ctx.translate(Math.round(x), Math.round(groundY));
  ctx.fillStyle = '#2f9e44';
  const puffs = [[0, -8 * s, 10 * s], [12 * s, -11 * s, 12 * s], [25 * s, -8 * s, 10 * s], [12 * s, -4 * s, 12 * s]];
  for (const [px, py, r] of puffs) {
    ctx.beginPath();
    ctx.arc(px, py, r, Math.PI, Math.PI * 2);
    ctx.fill();
  }
  ctx.fillRect(0, -4 * s, 25 * s, 4 * s);
  ctx.fillStyle = '#48c25c';
  ctx.beginPath();
  ctx.arc(12 * s, -11 * s, 9 * s, Math.PI * 1.05, Math.PI * 1.9);
  ctx.fill();
  ctx.restore();
}

function tileOffset(G, x, y) {
  const b = G.bumps.get(y * G.level.W + x);
  if (!b) return 0;
  return -7 * Math.sin(Math.PI * Math.min(1, b.t / b.dur));
}

function drawGroundTile(ctx, sx, sy, x, y, openAbove) {
  ctx.fillStyle = C.ground;
  ctx.fillRect(sx, sy, 16, 16);

  // speckled stone texture
  for (let i = 0; i < 4; i++) {
    const hx = hash(x * 4 + i, y * 7 + 1);
    const hy = hash(x * 9 + 3, y * 3 + i);
    ctx.fillStyle = hx > 0.5 ? C.groundShade : '#b96c30';
    ctx.fillRect(sx + 2 + Math.floor(hx * 11), sy + 5 + Math.floor(hy * 9), 2, 2);
  }

  ctx.fillStyle = C.groundDark;
  ctx.fillRect(sx, sy + 15, 16, 1);
  ctx.fillRect(sx + 15, sy, 1, 16);

  if (openAbove) {
    ctx.fillStyle = C.groundHi;
    ctx.fillRect(sx, sy, 16, 2);
    ctx.fillStyle = C.groundLight;
    ctx.fillRect(sx, sy + 2, 16, 3);
    ctx.fillStyle = 'rgba(0,0,0,0.08)';
    ctx.fillRect(sx, sy + 5, 16, 1);
  }
}

function drawBrickTile(ctx, sx, sy) {
  ctx.fillStyle = C.brick;
  ctx.fillRect(sx, sy, 16, 16);
  ctx.fillStyle = C.brickHi;
  ctx.fillRect(sx + 1, sy + 1, 14, 1);
  ctx.fillRect(sx + 1, sy + 1, 1, 6);
  ctx.fillStyle = C.brickDark;
  ctx.fillRect(sx, sy + 15, 16, 1);
  ctx.fillRect(sx + 15, sy, 1, 16);
  // mortar
  ctx.fillStyle = '#8f3a17';
  ctx.fillRect(sx + 1, sy + 7, 14, 1);
  ctx.fillRect(sx + 7, sy + 1, 1, 6);
  ctx.fillRect(sx + 3, sy + 8, 1, 7);
  ctx.fillRect(sx + 11, sy + 8, 1, 7);
  ctx.fillStyle = 'rgba(255,255,255,0.14)';
  ctx.fillRect(sx + 2, sy + 8, 5, 1);
}

function drawQuestionTile(ctx, sx, sy, t) {
  const pulse = 0.5 + 0.5 * Math.sin(t * 4);
  ctx.fillStyle = `rgba(255, 220, 120, ${0.16 + pulse * 0.2})`;
  ctx.fillRect(sx - 2, sy - 2, 20, 20);

  const g = ctx.createLinearGradient(0, sy, 0, sy + 16);
  g.addColorStop(0, '#ffe07a');
  g.addColorStop(0.5, '#f2b33d');
  g.addColorStop(1, '#d98d1c');
  ctx.fillStyle = g;
  ctx.fillRect(sx, sy, 16, 16);

  ctx.fillStyle = '#7a4a12';
  ctx.fillRect(sx, sy, 16, 1);
  ctx.fillRect(sx, sy + 15, 16, 1);
  ctx.fillRect(sx, sy, 1, 16);
  ctx.fillRect(sx + 15, sy, 1, 16);

  ctx.fillStyle = '#fff2b0';
  ctx.fillRect(sx + 1, sy + 1, 14, 1);
  ctx.fillRect(sx + 1, sy + 1, 1, 14);

  ctx.fillStyle = '#a86a12';
  for (const [dx, dy] of [[2, 2], [12, 2], [2, 12], [12, 12]]) {
    ctx.fillRect(sx + dx, sy + dy, 2, 2);
  }

  const bob = Math.round(Math.sin(t * 4) * 0.6);
  drawText(ctx, '?', sx + 8, sy + 3 + bob, 1, '#fff8e0', { align: 'center', shadow: '#9a5c0c' });
}

function drawUsedTile(ctx, sx, sy) {
  ctx.fillStyle = '#9c6238';
  ctx.fillRect(sx, sy, 16, 16);
  ctx.fillStyle = '#b97b4a';
  ctx.fillRect(sx + 1, sy + 1, 14, 2);
  ctx.fillStyle = '#6b3b1c';
  ctx.fillRect(sx, sy + 15, 16, 1);
  ctx.fillRect(sx + 15, sy, 1, 16);
  ctx.fillRect(sx, sy, 16, 1);
  ctx.fillRect(sx, sy, 1, 16);
  ctx.fillStyle = '#7f4c27';
  ctx.fillRect(sx + 2, sy + 4, 12, 1);
  ctx.fillRect(sx + 2, sy + 11, 12, 1);
}

function drawStoneTile(ctx, sx, sy) {
  ctx.fillStyle = C.stone;
  ctx.fillRect(sx, sy, 16, 16);
  ctx.fillStyle = C.stoneHi;
  ctx.fillRect(sx, sy, 16, 2);
  ctx.fillRect(sx, sy, 2, 16);
  ctx.fillStyle = C.stoneDark;
  ctx.fillRect(sx, sy + 15, 16, 1);
  ctx.fillRect(sx + 15, sy, 1, 16);
  ctx.fillStyle = 'rgba(0,0,0,0.08)';
  ctx.fillRect(sx + 4, sy + 6, 8, 1);
  ctx.fillRect(sx + 4, sy + 10, 8, 1);
}

function drawTiles(ctx, G) {
  const { level, cam } = G;
  const x0 = Math.max(0, Math.floor(cam.x / TILE));
  const x1 = Math.min(level.W - 1, Math.ceil((cam.x + VIEW_W) / TILE));
  const sy0 = Math.floor(cam.y / TILE);

  for (let y = sy0; y < level.H; y++) {
    for (let x = x0; x <= x1; x++) {
      const type = level.tiles[y * level.W + x];
      if (!type || type === T.PIPE) continue;
      const off = tileOffset(G, x, y);
      const sx = Math.round(x * TILE - cam.x);
      const sy = Math.round(y * TILE - cam.y + off);
      if (sy > VIEW_H + 16 || sy < -20) continue;

      if (type === T.GROUND) {
        const above = y > 0 ? level.tiles[(y - 1) * level.W + x] : 0;
        drawGroundTile(ctx, sx, sy, x, y, !above);
      } else if (type === T.BRICK) drawBrickTile(ctx, sx, sy);
      else if (type === T.QCOIN || type === T.QPOWER) drawQuestionTile(ctx, sx, sy, G.t + x * 0.37);
      else if (type === T.USED) drawUsedTile(ctx, sx, sy);
      else if (type === T.STONE) drawStoneTile(ctx, sx, sy);
    }
  }
}

function drawPipe(ctx, pipe, cam) {
  const x = Math.round(pipe.x - cam.x);
  const y = Math.round(pipe.y - cam.y);
  const w = pipe.w;
  const h = pipe.h;
  if (x + w < -10 || x > VIEW_W + 10) return;

  const rimH = 14;
  // body
  ctx.fillStyle = C.pipeDark;
  ctx.fillRect(x + 1, y + rimH - 2, w - 2, h - rimH + 2);
  ctx.fillStyle = C.pipe;
  ctx.fillRect(x + 3, y + rimH - 2, w - 6, h - rimH + 2);
  ctx.fillStyle = C.pipeHi;
  ctx.fillRect(x + 5, y + rimH - 2, 3, h - rimH + 2);
  ctx.fillStyle = 'rgba(0,0,0,0.14)';
  ctx.fillRect(x + w - 7, y + rimH - 2, 3, h - rimH + 2);

  // rim
  ctx.fillStyle = C.pipeDark;
  ctx.fillRect(x, y, w, rimH);
  ctx.fillStyle = C.pipe;
  ctx.fillRect(x + 1, y + 1, w - 2, rimH - 3);
  ctx.fillStyle = C.pipeHi;
  ctx.fillRect(x + 3, y + 2, 4, rimH - 5);
  ctx.fillStyle = '#0e4d22';
  ctx.fillRect(x, y + rimH - 2, w, 2);
  ctx.fillStyle = 'rgba(255,255,255,0.18)';
  ctx.fillRect(x + 1, y + 1, w - 2, 1);
}

function drawFlag(ctx, G) {
  const { level, cam } = G;
  const x = Math.round(level.flagX - cam.x);
  const groundY = level.groundTop - cam.y;
  const topY = groundY - 148;

  ctx.fillStyle = '#cfe0ef';
  ctx.fillRect(x - 1, topY, 3, 148);
  ctx.fillStyle = '#8fa8bd';
  ctx.fillRect(x + 1, topY, 1, 148);

  // ball on top
  ctx.fillStyle = '#ffd94a';
  ctx.beginPath();
  ctx.arc(x, topY - 3, 4.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#fff2b0';
  ctx.beginPath();
  ctx.arc(x - 1, topY - 4, 2, 0, Math.PI * 2);
  ctx.fill();

  // flag cloth
  const drop = G.flagDrop || 0;
  const fy = topY + 6 + drop * 110;
  const wave = Math.sin(G.t * 4) * 2;
  ctx.fillStyle = '#fff8ec';
  ctx.beginPath();
  ctx.moveTo(x - 2, fy);
  ctx.lineTo(x - 30, fy + 7 + wave);
  ctx.lineTo(x - 2, fy + 18);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#e33127';
  ctx.beginPath();
  ctx.arc(x - 12, fy + 9 + wave * 0.5, 4, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#fff8ec';
  ctx.fillRect(x - 13, fy + 6 + wave * 0.5, 2, 6);
  ctx.fillRect(x - 14, fy + 8 + wave * 0.5, 4, 2);
}

function drawCastle(ctx, level, cam) {
  const x = Math.round(level.castleX - cam.x);
  const groundY = level.groundTop - cam.y;
  const w = 112;
  const h = 96;
  const y = groundY - h;
  if (x > VIEW_W + 20 || x + w < -20) return;

  ctx.fillStyle = '#b04a2a';
  ctx.fillRect(x, y + 20, w, h - 20);
  ctx.fillStyle = '#c25a34';
  ctx.fillRect(x + 4, y + 24, w - 8, 10);

  // brick lines
  ctx.fillStyle = 'rgba(90, 30, 12, 0.45)';
  for (let row = 0; row < 5; row++) {
    ctx.fillRect(x, y + 34 + row * 12, w, 1);
    for (let col = 0; col < 7; col++) {
      ctx.fillRect(x + 8 + col * 16 + (row % 2) * 8, y + 34 + row * 12, 1, 12);
    }
  }

  // battlements
  ctx.fillStyle = '#b04a2a';
  for (let i = 0; i < 5; i++) {
    ctx.fillRect(x + 4 + i * 24, y, 14, 24);
    ctx.fillStyle = '#8f3a20';
    ctx.fillRect(x + 4 + i * 24, y + 20, 14, 4);
    ctx.fillStyle = '#b04a2a';
  }
  ctx.fillStyle = '#8f3a20';
  ctx.fillRect(x, y + 18, w, 4);

  // door
  ctx.fillStyle = '#2b1409';
  ctx.fillRect(x + w / 2 - 16, groundY - 46, 32, 46);
  ctx.beginPath();
  ctx.arc(x + w / 2, groundY - 46, 16, Math.PI, 0);
  ctx.fill();
  ctx.fillStyle = '#4a2412';
  ctx.fillRect(x + w / 2 - 12, groundY - 42, 24, 2);

  // windows
  ctx.fillStyle = '#2b1409';
  for (const wx of [x + 20, x + w - 32]) {
    ctx.fillRect(wx, y + 34, 12, 16);
    ctx.beginPath();
    ctx.arc(wx + 6, y + 34, 6, Math.PI, 0);
    ctx.fill();
  }

  // tower flag
  ctx.fillStyle = '#8fa8bd';
  ctx.fillRect(x + w / 2, y - 34, 2, 34);
  ctx.fillStyle = '#e33127';
  ctx.beginPath();
  ctx.moveTo(x + w / 2 + 2, y - 32);
  ctx.lineTo(x + w / 2 + 22, y - 26);
  ctx.lineTo(x + w / 2 + 2, y - 18);
  ctx.closePath();
  ctx.fill();
}

function drawHUD(ctx, G) {
  const t = G.t;
  const shadow = 'rgba(0,0,0,0.55)';
  const white = '#fff8ec';

  // soft scrim so the HUD stays readable over bright sky
  const g = ctx.createLinearGradient(0, 0, 0, 30);
  g.addColorStop(0, 'rgba(8, 18, 40, 0.35)');
  g.addColorStop(1, 'rgba(8, 18, 40, 0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, VIEW_W, 30);

  drawText(ctx, 'MARIO', 12, 5, 1, white, { shadow });
  drawText(ctx, String(G.score).padStart(6, '0'), 12, 14, 1, white, { shadow });

  // coins
  S.drawCoin(ctx, 104, 11, 3.6, t);
  drawText(ctx, 'x' + String(G.coins).padStart(2, '0'), 112, 8, 1, white, { shadow });

  // lives
  ctx.save();
  ctx.translate(12, 26);
  ctx.scale(0.42, 0.42);
  ctx.fillStyle = '#e33127';
  ctx.fillRect(2, 0, 8, 2);
  ctx.fillRect(1, 2, 10, 1);
  ctx.fillStyle = '#ffc39b';
  ctx.fillRect(3, 3, 7, 4);
  ctx.fillStyle = '#241407';
  ctx.fillRect(7, 4, 1, 2);
  ctx.fillStyle = '#5a2c10';
  ctx.fillRect(4, 6, 4, 1);
  ctx.restore();
  drawText(ctx, 'x' + G.lives, 20, 23, 1, white, { shadow });

  // world
  drawText(ctx, 'WORLD', 212, 5, 1, white, { align: 'center', shadow });
  drawText(ctx, '1-1', 212, 14, 1, white, { align: 'center', shadow });

  // time
  drawText(ctx, 'TIME', 330, 5, 1, white, { align: 'center', shadow });
  const timeStr = String(Math.max(0, Math.ceil(G.time))).padStart(3, '0');
  drawText(ctx, timeStr, 330, 14, 1, G.time <= 30 ? '#ff8a7a' : white, { align: 'center', shadow });
}

function drawParticles(ctx, G) {
  const { cam } = G;
  for (const p of G.particles) {
    const alpha = Math.max(0, Math.min(1, p.life / p.maxLife));
    const x = p.x - cam.x;
    const y = p.y - cam.y;
    ctx.globalAlpha = alpha;
    if (p.kind === 'debris') {
      ctx.fillStyle = p.color;
      ctx.fillRect(Math.round(x), Math.round(y), p.size, p.size);
    } else if (p.kind === 'spark') {
      ctx.fillStyle = p.color;
      ctx.fillRect(Math.round(x - p.size / 2), Math.round(y - p.size / 2), p.size, p.size);
    } else if (p.kind === 'dust') {
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(x, y, p.size * (0.6 + (1 - alpha) * 1.2), 0, Math.PI * 2);
      ctx.fill();
    } else if (p.kind === 'text') {
      drawText(ctx, p.text, x, y, 1, p.color, { align: 'center', shadow: 'rgba(0,0,0,0.5)' });
    } else if (p.kind === 'coinpop') {
      S.drawCoin(ctx, x, y, 5, G.t * 2);
    }
    ctx.globalAlpha = 1;
  }
}

function drawEnemies(ctx, G) {
  const { cam } = G;
  for (const e of G.enemies) {
    if (e.remove) continue;
    const x = e.x - cam.x;
    const y = e.y - cam.y;
    if (x > VIEW_W + 40 || x + e.w < -40) continue;
    if (e.type === 'goomba') {
      S.drawGoomba(ctx, x, y, e.w, e.h, e);
    } else if (e.type === 'koopa') {
      S.drawKoopa(ctx, x, y, e.w, e.h, e);
    } else if (e.type === 'piranha') {
      S.drawPiranha(ctx, x + e.w / 2, y + e.h, e.plantH, G.t, e.open);
    }
  }
}

function drawItems(ctx, G) {
  const { cam } = G;
  for (const it of G.items) {
    if (it.remove) continue;
    const x = it.x - cam.x;
    const y = it.y - cam.y;
    if (x > VIEW_W + 40 || x + it.w < -40) continue;
    if (it.type === 'mushroom') S.drawMushroom(ctx, x, y, it.w, it.h);
    else if (it.type === 'flower') S.drawFlower(ctx, x, y, it.w, it.h, G.t);
    else if (it.type === 'fireball') S.drawFireball(ctx, x + it.w / 2, y + it.h / 2, G.t);
  }
}

function drawPlayer(ctx, G) {
  const p = G.player;
  if (!p.visible) return;
  const x = p.x - G.cam.x;
  const y = p.y - G.cam.y;
  S.drawMario(ctx, x, y, p.w, p.h, {
    power: p.power,
    facing: p.facing,
    onGround: p.onGround,
    vx: p.vx,
    vy: p.vy,
    skid: p.skid,
    dead: p.dead,
    walkPhase: p.walkPhase,
    glow: p.invuln > 0 && Math.floor(G.t * 20) % 2 === 0,
  });
}

export function render(ctx, G) {
  const { level, cam } = G;
  const shakeX = G.shake > 0 ? (Math.random() - 0.5) * 4 : 0;
  const shakeY = G.shake > 0 ? (Math.random() - 0.5) * 4 : 0;

  ctx.save();
  ctx.setTransform(G.pixelScale, 0, 0, G.pixelScale, 0, 0);
  ctx.translate(shakeX, shakeY);

  drawSky(ctx, cam, G.t);

  for (const c of level.clouds) {
    const x = c.x - cam.x * 0.22;
    if (x < -120 || x > VIEW_W + 120) continue;
    drawCloud(ctx, x, c.y - cam.y * 0.2, c.size);
  }

  for (const h of level.hills) {
    const x = h.x - cam.x * 0.5;
    if (x < -120 || x > VIEW_W + 120) continue;
    drawHill(ctx, x, level.groundTop - cam.y + 1, h.size);
  }

  for (const b of level.bushes) {
    const x = b.x - cam.x;
    if (x < -80 || x > VIEW_W + 80) continue;
    drawBush(ctx, x, level.groundTop - cam.y + 2, b.size);
  }

  drawCastle(ctx, level, cam);

  for (const e of G.enemies) {
    if (e.type === 'piranha' && !e.remove) {
      const x = e.x + e.w / 2 - cam.x;
      if (x > -40 && x < VIEW_W + 40) {
        // draw the plant behind the pipe rim
        S.drawPiranha(ctx, x, e.y + e.h - cam.y, e.plantH, G.t, e.open);
      }
    }
  }

  for (const pipe of level.pipes) drawPipe(ctx, pipe, cam);

  drawTiles(ctx, G);

  for (const coin of G.coins) {
    if (coin.taken) continue;
    const x = coin.x - cam.x;
    const y = coin.y - cam.y;
    if (x < -20 || x > VIEW_W + 20) continue;
    S.drawCoin(ctx, x, y + Math.sin(G.t * 3 + coin.x * 0.1) * 1.2, 5, G.t + coin.x * 0.05);
  }

  drawFlag(ctx, G);
  drawEnemies(ctx, G);
  drawItems(ctx, G);
  drawPlayer(ctx, G);
  drawParticles(ctx, G);
  drawHUD(ctx, G);

  if (G.state === 'pause') {
    ctx.fillStyle = 'rgba(6, 10, 24, 0.55)';
    ctx.fillRect(0, 0, VIEW_W, VIEW_H);
    drawText(ctx, 'PAUSED', VIEW_W / 2, VIEW_H / 2 - 26, 3, '#fff8ec', { align: 'center', shadow: '#0a1024' });
    drawText(ctx, 'PRESS P TO RESUME', VIEW_W / 2, VIEW_H / 2 + 8, 1, '#cfd9f5', { align: 'center', shadow: '#0a1024' });
  }

  ctx.restore();
}

import { buildLevel, TILE, T } from './level.js';
import { render, VIEW_W, VIEW_H } from './render.js';
import { Sound } from './audio.js';

const PIXEL_SCALE = 2;
const GRAVITY = 1500;
const MAX_FALL = 520;
const WALK_SPEED = 100;
const RUN_SPEED = 172;
const ACCEL = 640;
const AIR_ACCEL = 520;
const FRICTION = 620;
const AIR_FRICTION = 120;
const JUMP_V = -468;
const JUMP_CUT = -165;
const COYOTE = 0.09;
const JUMP_BUFFER = 0.12;

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d', { alpha: false });
canvas.width = VIEW_W * PIXEL_SCALE;
canvas.height = VIEW_H * PIXEL_SCALE;
ctx.imageSmoothingEnabled = false;

const overlay = document.getElementById('overlay');
const soundBtn = document.getElementById('soundBtn');
const pauseBtn = document.getElementById('pauseBtn');
const touch = document.getElementById('touch');
const sound = new Sound();

const input = {
  left: false, right: false, jump: false, run: false,
  jumpPressed: false, runPressed: false,
};

const G = {
  state: 'title',
  level: null,
  player: null,
  cam: { x: 0, y: 15 },
  score: 0,
  coinCount: 0,
  lives: 3,
  time: 300,
  t: 0,
  enemies: [],
  items: [],
  particles: [],
  coinList: [],
  bumps: new Map(),
  shake: 0,
  flagDrop: 0,
  flagPhase: '',
  stateTimer: 0,
  pixelScale: PIXEL_SCALE,
  viewW: VIEW_W,
  viewH: VIEW_H,
  stompCombo: 0,
};

// ---------------------------------------------------------------------------
// Setup / reset
// ---------------------------------------------------------------------------

function makePlayer() {
  return {
    x: 3 * TILE,
    y: G.level.groundTop - 15,
    w: 11,
    h: 15,
    vx: 0,
    vy: 0,
    onGround: true,
    facing: 1,
    power: 0,
    invuln: 0,
    walkPhase: 0,
    skid: false,
    dead: false,
    visible: true,
    coyote: 0,
    buffer: 0,
    jumpCut: false,
    fireCooldown: 0,
  };
}

function createEnemies(level) {
  return level.enemies.map((spawn) => {
    if (spawn.type === 'goomba') {
      return {
        type: 'goomba', x: spawn.tx * TILE + 1, y: level.groundTop - 14,
        w: 14, h: 14, vx: -42, vy: 0, state: 'walk', anim: 0, timer: 0,
        awake: false, remove: false,
      };
    }
    return {
      type: 'koopa', x: spawn.tx * TILE + 1, y: level.groundTop - 22,
      w: 14, h: 22, vx: -46, vy: 0, state: 'walk', anim: 0, timer: 0,
      awake: false, remove: false, facing: -1,
    };
  });
}

function createPiranhas(level) {
  const plants = [];
  for (const pipe of level.pipes) {
    if (!pipe.plant) continue;
    plants.push({
      type: 'piranha',
      x: pipe.x + pipe.w / 2 - 7,
      y: pipe.y,
      w: 14,
      h: 0,
      plantH: 0,
      phase: 'hidden',
      timer: 1 + Math.random() * 1.5,
      open: false,
      remove: false,
      awake: true,
    });
  }
  return plants;
}

function resetLevel() {
  G.level = buildLevel();
  G.player = makePlayer();
  G.enemies = [...createEnemies(G.level), ...createPiranhas(G.level)];
  G.items = [];
  G.particles = [];
  G.coinList = G.level.coins.map((c) => ({ ...c, taken: false }));
  G.bumps.clear();
  G.cam.x = 0;
  G.cam.y = G.level.height - VIEW_H;
  G.flagDrop = 0;
  G.flagPhase = '';
  G.stompCombo = 0;
  G.shake = 0;
}

function startGame() {
  sound.ensure();
  sound.setMuted(sound.muted);
  overlay.classList.remove('show');
  resetLevel();
  G.score = 0;
  G.coinCount = 0;
  G.lives = 3;
  G.time = 300;
  G.t = 0;
  G.state = 'play';
  G.stateTimer = 0;
  input.left = input.right = input.jump = input.run = false;
  input.jumpPressed = input.runPressed = false;
  sound.startMusic();
}

function respawn() {
  resetLevel();
  G.time = 300;
  G.state = 'play';
  G.stateTimer = 0;
  input.jumpPressed = input.runPressed = false;
  sound.startMusic();
}

// ---------------------------------------------------------------------------
// Collision helpers
// ---------------------------------------------------------------------------

function isSolid(tx, ty) {
  const level = G.level;
  if (tx < 0 || tx >= level.W) return true;
  if (ty < 0) return false;
  if (ty >= level.H) return false;
  return level.solid[ty * level.W + tx] === 1;
}

function moveX(e, dt, stopOnHit = true) {
  e.hitWall = false;
  e.x += e.vx * dt;
  const y0 = Math.floor(e.y / TILE);
  const y1 = Math.floor((e.y + e.h - 0.01) / TILE);

  if (e.vx > 0) {
    const tx = Math.floor((e.x + e.w - 0.01) / TILE);
    for (let ty = y0; ty <= y1; ty++) {
      if (isSolid(tx, ty)) {
        e.x = tx * TILE - e.w;
        e.hitWall = true;
        if (stopOnHit) e.vx = 0;
        return;
      }
    }
  } else if (e.vx < 0) {
    const tx = Math.floor(e.x / TILE);
    for (let ty = y0; ty <= y1; ty++) {
      if (isSolid(tx, ty)) {
        e.x = (tx + 1) * TILE;
        e.hitWall = true;
        if (stopOnHit) e.vx = 0;
        return;
      }
    }
  }
}

function moveY(e, dt, onHeadHit = null) {
  e.y += e.vy * dt;
  const x0 = Math.floor(e.x / TILE);
  const x1 = Math.floor((e.x + e.w - 0.01) / TILE);

  if (e.vy > 0) {
    const ty = Math.floor((e.y + e.h - 0.01) / TILE);
    for (let tx = x0; tx <= x1; tx++) {
      if (isSolid(tx, ty)) {
        e.y = ty * TILE - e.h;
        e.vy = 0;
        e.onGround = true;
        return;
      }
    }
  } else if (e.vy < 0) {
    const ty = Math.floor(e.y / TILE);
    for (let tx = x0; tx <= x1; tx++) {
      if (isSolid(tx, ty)) {
        e.y = (ty + 1) * TILE;
        e.vy = 0;
        if (onHeadHit) onHeadHit(tx, ty);
        return;
      }
    }
  }
}

function overlaps(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

// ---------------------------------------------------------------------------
// Effects
// ---------------------------------------------------------------------------

function spawnParticles(x, y, count, opts = {}) {
  const {
    color = '#ffd75e', speed = 90, size = 2, kind = 'spark', gravity = 600, life = 0.5, spread = Math.PI * 2,
  } = opts;
  for (let i = 0; i < count; i++) {
    const angle = Math.random() * spread - spread / 2 - Math.PI / 2;
    const mag = speed * (0.4 + Math.random() * 0.8);
    G.particles.push({
      kind,
      x, y,
      vx: Math.cos(angle) * mag,
      vy: Math.sin(angle) * mag,
      gravity,
      size: size * (0.6 + Math.random() * 0.8),
      color,
      life: life * (0.6 + Math.random() * 0.7),
      maxLife: life,
    });
  }
}

function popText(x, y, text, color = '#fff8ec') {
  G.particles.push({
    kind: 'text', x, y, vx: 0, vy: -42, gravity: 0, size: 1,
    color, text, life: 0.9, maxLife: 0.9,
  });
}

function dustPuff(x, y, dir = 0) {
  G.particles.push({
    kind: 'dust', x, y, vx: dir * 20 + (Math.random() - 0.5) * 20, vy: -12 - Math.random() * 12,
    gravity: -10, size: 2.5, color: 'rgba(255,255,255,0.85)', life: 0.35, maxLife: 0.35,
  });
}

function addScore(points, x, y) {
  G.score += points;
  if (x !== undefined) popText(x, y, String(points));
}

// ---------------------------------------------------------------------------
// Blocks
// ---------------------------------------------------------------------------

function bumpBlock(tx, ty) {
  G.bumps.set(ty * G.level.W + tx, { t: 0, dur: 0.24 });
}

function breakBrick(tx, ty) {
  const level = G.level;
  const i = ty * level.W + tx;
  level.tiles[i] = T.EMPTY;
  level.solid[i] = 0;
  const cx = tx * TILE + 8;
  const cy = ty * TILE + 8;
  for (const [dx, dy] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
    G.particles.push({
      kind: 'debris', x: cx + dx * 4, y: cy + dy * 4,
      vx: dx * 90 + (Math.random() - 0.5) * 40,
      vy: dy * 140 - 120,
      gravity: 900, size: 4, color: dx * dy > 0 ? '#cf5a2e' : '#e8834f',
      life: 1, maxLife: 1,
    });
  }
  spawnParticles(cx, cy, 5, { color: '#ffd9a8', speed: 70, size: 2, life: 0.35 });
  sound.brick();
}

function spawnCoinPop(tx, ty) {
  G.particles.push({
    kind: 'coinpop', x: tx * TILE + 8, y: ty * TILE - 4,
    vx: 0, vy: -190, gravity: 700, size: 1, color: '#ffd75e',
    life: 0.55, maxLife: 0.55,
  });
}

function spawnPower(tx, ty) {
  const type = G.player.power === 0 ? 'mushroom' : 'flower';
  const w = 14;
  const h = 14;
  G.items.push({
    type,
    x: tx * TILE + 1,
    y: ty * TILE,
    w, h,
    vx: 0,
    vy: 0,
    emerge: 0.5,
    emergeFrom: ty * TILE,
    targetY: ty * TILE - h,
    onGround: false,
    remove: false,
  });
  sound.grow();
}

function hitBlock(tx, ty) {
  const level = G.level;
  const i = ty * level.W + tx;
  const type = level.tiles[i];

  if (type === T.BRICK) {
    if (G.player.power > 0) {
      breakBrick(tx, ty);
      addScore(50, tx * TILE + 8, ty * TILE);
    } else {
      bumpBlock(tx, ty);
      sound.bump();
    }
    bumpEnemiesOn(tx, ty);
  } else if (type === T.QCOIN || type === T.QPOWER) {
    level.tiles[i] = T.USED;
    bumpBlock(tx, ty);
    bumpEnemiesOn(tx, ty);
    if (type === T.QCOIN) {
      G.coinCount += 1;
      addScore(200, tx * TILE + 8, ty * TILE - 6);
      spawnCoinPop(tx, ty);
      sound.coin();
    } else {
      spawnPower(tx, ty);
    }
  } else if (type === T.STONE || type === T.USED || type === T.GROUND) {
    bumpBlock(tx, ty);
    sound.bump();
    bumpEnemiesOn(tx, ty);
  }
}

function bumpEnemiesOn(tx, ty) {
  const top = ty * TILE;
  for (const e of G.enemies) {
    if (e.remove || e.type === 'piranha') continue;
    const feet = e.y + e.h;
    if (Math.abs(feet - top) < 5 && e.x + e.w > tx * TILE && e.x < (tx + 1) * TILE) {
      e.state = 'flip';
      e.vy = -240;
      e.vx = (Math.random() - 0.5) * 40;
      addScore(100, e.x + e.w / 2, e.y);
    }
  }
}

// ---------------------------------------------------------------------------
// Player
// ---------------------------------------------------------------------------

function setPower(p, power) {
  const oldH = p.h;
  const oldW = p.w;
  p.power = power;
  p.h = power > 0 ? 28 : 15;
  p.w = power > 0 ? 12 : 11;
  p.y -= p.h - oldH;
  p.x += (oldW - p.w) / 2;
}

function damagePlayer() {
  const p = G.player;
  if (G.state !== 'play' || p.invuln > 0) return;
  if (p.power > 0) {
    setPower(p, 0);
    p.invuln = 2;
    G.shake = 0.25;
    sound.hurt();
    spawnParticles(p.x + p.w / 2, p.y + p.h / 2, 8, { color: '#ffffff', speed: 80, size: 2, life: 0.4 });
  } else {
    killPlayer();
  }
}

function killPlayer() {
  const p = G.player;
  if (G.state === 'dead') return;
  G.state = 'dead';
  G.stateTimer = 0;
  p.dead = true;
  p.vx = 0;
  p.vy = -360;
  p.onGround = false;
  p.invuln = 0;
  G.shake = 0.3;
  sound.die();
  sound.stopMusic();
}

function collectCoin(coin) {
  coin.taken = true;
  G.coinCount += 1;
  G.score += 200;
  sound.coin();
  spawnParticles(coin.x, coin.y, 5, { color: '#ffe9a3', speed: 70, size: 2, life: 0.4 });
  if (G.coinCount >= 100) {
    G.coinCount -= 100;
    G.lives += 1;
    sound.power();
    popText(G.player.x + G.player.w / 2, G.player.y - 8, '1UP', '#8ef58e');
  }
}

function updatePlayer(dt) {
  const p = G.player;

  if (p.invuln > 0) p.invuln = Math.max(0, p.invuln - dt);
  if (p.fireCooldown > 0) p.fireCooldown = Math.max(0, p.fireCooldown - dt);

  const dir = (input.right ? 1 : 0) - (input.left ? 1 : 0);
  const maxSpeed = input.run ? RUN_SPEED : WALK_SPEED;
  const accel = p.onGround ? ACCEL : AIR_ACCEL;

  p.skid = p.onGround && dir !== 0 && p.vx * dir < -8 && Math.abs(p.vx) > 24;

  if (dir !== 0) {
    if (p.skid) {
      p.vx += dir * accel * 2.1 * dt;
      if (Math.random() < 0.4) dustPuff(p.x + p.w / 2, p.y + p.h, -dir);
    } else {
      p.vx += dir * accel * dt;
    }
    p.facing = dir;
    if (Math.abs(p.vx) > maxSpeed) {
      const excess = Math.abs(p.vx) - maxSpeed;
      p.vx -= Math.sign(p.vx) * Math.min(excess, FRICTION * dt);
    }
  } else {
    const f = (p.onGround ? FRICTION : AIR_FRICTION) * dt;
    if (Math.abs(p.vx) <= f) p.vx = 0;
    else p.vx -= Math.sign(p.vx) * f;
  }

  // jump buffering + coyote time
  if (input.jumpPressed) {
    p.buffer = JUMP_BUFFER;
    input.jumpPressed = false;
  }
  if (p.onGround) p.coyote = COYOTE;
  else p.coyote = Math.max(0, p.coyote - dt);
  p.buffer = Math.max(0, p.buffer - dt);

  if (p.buffer > 0 && p.coyote > 0) {
    p.vy = JUMP_V - Math.min(Math.abs(p.vx), RUN_SPEED) * 0.1;
    p.buffer = 0;
    p.coyote = 0;
    p.onGround = false;
    p.jumpCut = false;
    if (p.power > 0) sound.bigJump(); else sound.jump();
    dustPuff(p.x + p.w / 2, p.y + p.h, 0);
  }

  if (!input.jump && p.vy < JUMP_CUT && !p.jumpCut) {
    p.vy = JUMP_CUT;
    p.jumpCut = true;
  }
  if (p.vy >= 0) p.jumpCut = false;

  // fireballs
  if (input.runPressed) {
    input.runPressed = false;
    if (p.power === 2 && p.fireCooldown <= 0) {
      const active = G.items.filter((it) => it.type === 'fireball' && !it.remove).length;
      if (active < 2) {
        G.items.push({
          type: 'fireball',
          x: p.facing > 0 ? p.x + p.w : p.x - 7,
          y: p.y + p.h * 0.4,
          w: 7, h: 7,
          vx: p.facing * 240,
          vy: 60,
          onGround: false,
          remove: false,
          life: 3,
        });
        p.fireCooldown = 0.22;
        sound.fire();
      }
    }
  }

  // gravity + movement
  p.vy = Math.min(MAX_FALL, p.vy + GRAVITY * dt);
  p.onGround = false;
  moveX(p, dt, true);
  moveY(p, dt, hitBlock);

  if (p.onGround && Math.abs(p.vx) > 4) {
    p.walkPhase += Math.abs(p.vx) * dt * 0.075;
  } else if (p.onGround) {
    p.walkPhase = 0;
  }

  // pick up coins
  for (const coin of G.coinList) {
    if (coin.taken) continue;
    const box = { x: coin.x - 6, y: coin.y - 6, w: 12, h: 12 };
    if (overlaps(p, box)) collectCoin(coin);
  }

  if (p.x < 0) { p.x = 0; p.vx = Math.max(0, p.vx); }
  if (p.x + p.w > G.level.width) { p.x = G.level.width - p.w; p.vx = Math.min(0, p.vx); }

  if (p.y > G.level.height + 40) killPlayer();

  // flag pole
  if (p.x + p.w >= G.level.flagX && p.x < G.level.flagX + 10) startFlag();
}

// ---------------------------------------------------------------------------
// Enemies
// ---------------------------------------------------------------------------

function updateEnemies(dt) {
  const p = G.player;

  for (const e of G.enemies) {
    if (e.remove) continue;

    if (e.type === 'piranha') {
      updatePiranha(e, dt);
      if (e.plantH > 4 && G.state === 'play') {
        const box = { x: e.x + 1, y: e.y - e.plantH - 10, w: 12, h: e.plantH + 10 };
        if (overlaps(p, box)) damagePlayer();
      }
      continue;
    }

    if (!e.awake) {
      if (e.x < G.cam.x + VIEW_W + 140) e.awake = true;
      else continue;
    }

    if (e.state === 'squash') {
      e.timer -= dt;
      if (e.timer <= 0) e.remove = true;
      continue;
    }

    if (e.state === 'flip') {
      e.vy += GRAVITY * dt;
      e.x += e.vx * dt;
      e.y += e.vy * dt;
      if (e.y > G.level.height + 60) e.remove = true;
      continue;
    }

    e.anim += dt;
    e.vy = Math.min(MAX_FALL, e.vy + GRAVITY * dt);
    e.onGround = false;

    if (e.state === 'shell') {
      if (e.vx === 0) {
        e.timer += dt;
      }
      moveX(e, dt, false);
      if (e.hitWall) { e.vx = -e.vx; sound.bump(); }
      moveY(e, dt);
      if (e.y > G.level.height + 40) e.remove = true;
    } else {
      moveX(e, dt, false);
      if (e.hitWall) {
        e.vx = -e.vx;
        e.facing = e.vx > 0 ? 1 : -1;
      }
      moveY(e, dt);
      if (e.y > G.level.height + 40) e.remove = true;
    }

    if (G.state !== 'play') continue;

    // shell smashes other enemies
    if (e.type === 'koopa' && e.state === 'shell' && Math.abs(e.vx) > 100) {
      for (const other of G.enemies) {
        if (other === e || other.remove || other.type === 'piranha' || other.state === 'flip') continue;
        if (overlaps(e, other)) {
          other.state = 'flip';
          other.vy = -260;
          other.vx = Math.sign(e.vx) * 40;
          addScore(200, other.x + other.w / 2, other.y);
          sound.kick();
        }
      }
    }

    if (!overlaps(p, e)) continue;

    const feet = p.y + p.h;
    const stomping = p.vy > 0 && feet - e.y < 14;

    if (e.type === 'koopa' && e.state === 'shell') {
      if (stomping) {
        p.vy = input.jump ? -350 : -260;
        p.y = e.y - p.h;
        if (Math.abs(e.vx) > 100) {
          e.vx = 0;
          e.timer = 0;
          sound.stomp();
        } else {
          e.vx = (p.x + p.w / 2 < e.x + e.w / 2 ? 1 : -1) * 320;
          sound.kick();
          addScore(400, e.x + e.w / 2, e.y);
        }
      } else if (Math.abs(e.vx) > 100) {
        damagePlayer();
      } else {
        e.vx = (p.x + p.w / 2 < e.x + e.w / 2 ? 1 : -1) * 320;
        sound.kick();
        addScore(400, e.x + e.w / 2, e.y);
      }
      continue;
    }

    if (stomping) {
      p.vy = input.jump ? -360 : -260;
      p.y = e.y - p.h;
      G.stompCombo = Math.min(G.stompCombo + 1, 5);
      if (e.type === 'goomba') {
        e.state = 'squash';
        e.timer = 0.45;
        addScore(100 * G.stompCombo, e.x + e.w / 2, e.y);
      } else {
        const oldH = e.h;
        e.state = 'shell';
        e.h = 14;
        e.y += oldH - e.h;
        e.vx = 0;
        e.timer = 0;
        addScore(100, e.x + e.w / 2, e.y);
      }
      sound.stomp();
      G.shake = 0.12;
      spawnParticles(e.x + e.w / 2, e.y + 2, 4, { color: '#fff3d6', speed: 60, size: 2, life: 0.3 });
    } else {
      damagePlayer();
    }
  }
}

function updatePiranha(e, dt) {
  const p = G.player;
  const cx = e.x + e.w / 2;
  const near = Math.abs(p.x + p.w / 2 - cx) < 34;
  e.timer -= dt;

  if (e.phase === 'hidden') {
    if (e.timer <= 0 && !near) {
      e.phase = 'rise';
      e.timer = 0.45;
    }
  } else if (e.phase === 'rise') {
    e.plantH = Math.min(26, e.plantH + 70 * dt);
    if (e.plantH >= 26) {
      e.phase = 'out';
      e.timer = 1.5;
    }
  } else if (e.phase === 'out') {
    if (e.timer <= 0 || near) {
      e.phase = 'lower';
      e.timer = 0.35;
    }
  } else if (e.phase === 'lower') {
    e.plantH = Math.max(0, e.plantH - 90 * dt);
    if (e.plantH <= 0) {
      e.phase = 'hidden';
      e.timer = 2 + Math.random();
    }
  }
  e.open = e.phase === 'out' && Math.sin(G.t * 9) > 0.2;
}

// ---------------------------------------------------------------------------
// Items & fireballs
// ---------------------------------------------------------------------------

function updateItems(dt) {
  const p = G.player;

  for (const it of G.items) {
    if (it.remove) continue;

    if (it.type === 'fireball') {
      it.life -= dt;
      if (it.life <= 0) { it.remove = true; continue; }
      it.vy = Math.min(460, it.vy + 900 * dt);
      it.onGround = false;
      moveX(it, dt, true);
      if (it.hitWall) {
        it.remove = true;
        spawnParticles(it.x + 3, it.y + 3, 5, { color: '#ffb347', speed: 80, size: 2, life: 0.3 });
        continue;
      }
      const prevVy = it.vy;
      moveY(it, dt);
      if (it.onGround) {
        it.vy = -250;
      }
      if (it.y > G.level.height + 20) { it.remove = true; continue; }

      // hit enemies
      for (const e of G.enemies) {
        if (e.remove || e.state === 'squash') continue;
        const box = e.type === 'piranha'
          ? { x: e.x + 1, y: e.y - e.plantH - 10, w: 12, h: e.plantH + 10 }
          : e;
        if (e.type === 'piranha' && e.plantH < 4) continue;
        if (overlaps(it, box)) {
          e.remove = true;
          it.remove = true;
          addScore(200, e.x + e.w / 2, e.y);
          spawnParticles(e.x + e.w / 2, e.y, 10, { color: '#ffb347', speed: 110, size: 2.5, life: 0.45 });
          sound.kick();
          break;
        }
      }
      continue;
    }

    if (it.emerge > 0) {
      it.emerge = Math.max(0, it.emerge - dt);
      const k = 1 - it.emerge / 0.5;
      it.y = it.emergeFrom + (it.targetY - it.emergeFrom) * k;
      continue;
    }

    if (it.type === 'mushroom') {
      it.vx = it.vx || 58;
      it.vy = Math.min(MAX_FALL, it.vy + GRAVITY * dt);
      it.onGround = false;
      moveX(it, dt, false);
      if (it.hitWall) it.vx = -it.vx;
      moveY(it, dt);
      if (it.y > G.level.height + 30) it.remove = true;
    }

    if (G.state === 'play' && overlaps(p, it)) {
      it.remove = true;
      if (it.type === 'mushroom') {
        if (p.power === 0) {
          setPower(p, 1);
          sound.power();
          addScore(1000, p.x + p.w / 2, p.y);
          spawnParticles(p.x + p.w / 2, p.y + p.h / 2, 12, { color: '#ffe9a3', speed: 100, size: 2.5, life: 0.5 });
        } else {
          addScore(1000, p.x + p.w / 2, p.y);
        }
      } else if (it.type === 'flower') {
        setPower(p, 2);
        sound.power();
        addScore(1000, p.x + p.w / 2, p.y);
        spawnParticles(p.x + p.w / 2, p.y + p.h / 2, 14, { color: '#ffb347', speed: 110, size: 2.5, life: 0.55 });
      }
    }
  }

  G.items = G.items.filter((it) => !it.remove);
  G.enemies = G.enemies.filter((e) => !e.remove);
}

// ---------------------------------------------------------------------------
// Level flow
// ---------------------------------------------------------------------------

function startFlag() {
  if (G.state !== 'play') return;
  G.state = 'flag';
  G.flagPhase = 'slide';
  G.stateTimer = 0;
  const p = G.player;
  p.vx = 0;
  p.vy = 0;
  p.x = G.level.flagX - p.w + 2;
  p.facing = 1;
  G.flagDrop = 0;
  G.score += Math.max(0, Math.round((G.level.groundTop - p.y - p.h) / 3));
  sound.flag();
  sound.stopMusic();
}

function updateFlag(dt) {
  const p = G.player;
  G.stateTimer += dt;

  if (G.flagPhase === 'slide') {
    p.y += 95 * dt;
    G.flagDrop = Math.min(1, G.flagDrop + dt * 1.5);
    if (p.y + p.h >= G.level.groundTop) {
      p.y = G.level.groundTop - p.h;
      G.flagPhase = 'walk';
      G.stateTimer = 0;
    }
  } else if (G.flagPhase === 'walk') {
    p.facing = 1;
    p.x += 74 * dt;
    p.walkPhase += dt * 6;
    p.onGround = true;
    if (p.x > G.level.castleX + 40) {
      G.flagPhase = 'done';
      G.stateTimer = 0;
      G.state = 'clear';
      const bonus = Math.floor(G.time) * 10;
      G.score += bonus;
      if (bonus > 0) popText(p.x, p.y - 20, String(bonus), '#ffe9a3');
      sound.clear();
      setTimeout(() => {
        if (G.state === 'clear') showResult('Course Clear!', 'World 1-1 complete', `Score ${G.score} · Coins ${G.coinCount}`);
      }, 1400);
    }
  }
}

function showResult(title, kicker, sub) {
  G.state = 'over';
  overlay.innerHTML = `
    <div class="panel">
      <p class="eyebrow">${kicker}</p>
      <h1 class="result">${title}</h1>
      <p class="sub">${sub}</p>
      <button class="btn" type="button">Play Again</button>
      <p class="keys"><span class="desk">Press ENTER or tap the button</span><span class="touchhint">Tap to play again</span></p>
    </div>`;
  overlay.classList.add('show');
  sound.stopMusic();
}

function updateCamera(dt) {
  const p = G.player;
  const target = p.x + p.w / 2 - VIEW_W * 0.42;
  const maxX = Math.max(0, G.level.width - VIEW_W);
  G.cam.x += (target - G.cam.x) * Math.min(1, dt * 8);
  G.cam.x = Math.max(0, Math.min(maxX, G.cam.x));
}

function updateParticles(dt) {
  for (const p of G.particles) {
    p.life -= dt;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.vy += p.gravity * dt;
  }
  G.particles = G.particles.filter((p) => p.life > 0);
}

function updateBumps(dt) {
  for (const [key, bump] of G.bumps) {
    bump.t += dt;
    if (bump.t >= bump.dur) G.bumps.delete(key);
  }
}

// ---------------------------------------------------------------------------
// Main loop
// ---------------------------------------------------------------------------

function update(dt) {
  G.t += dt;
  if (G.shake > 0) G.shake = Math.max(0, G.shake - dt);

  if (G.state === 'title') {
    G.player.onGround = true;
    G.player.walkPhase = 0;
    return;
  }

  if (G.state === 'pause' || G.state === 'over') return;

  updateBumps(dt);
  updateParticles(dt);

  if (G.state === 'play') {
    G.time -= dt * 2.5;
    if (G.time <= 30 && Math.ceil(G.time) !== Math.ceil(G.time + dt * 2.5)) {
      if (G.time > 0) sound.tick();
    }
    if (G.time <= 0) {
      G.time = 0;
      killPlayer();
    }
    updatePlayer(dt);
    updateEnemies(dt);
    updateItems(dt);
    updateCamera(dt);
  } else if (G.state === 'dead') {
    G.stateTimer += dt;
    const p = G.player;
    p.vy = Math.min(MAX_FALL, p.vy + GRAVITY * dt);
    p.y += p.vy * dt;
    if (G.stateTimer > 2.1) {
      G.lives -= 1;
      if (G.lives <= 0) {
        showResult('Game Over', 'Out of lives', `Score ${G.score} · Coins ${G.coinCount}`);
      } else {
        respawn();
      }
    }
  } else if (G.state === 'flag') {
    updateFlag(dt);
    updateEnemies(dt);
    updateCamera(dt);
  } else if (G.state === 'clear') {
    updateEnemies(dt);
    updateCamera(dt);
  }
}

let lastTime = performance.now();
let accumulator = 0;
const STEP = 1 / 120;

function frame(now) {
  const elapsed = Math.min(0.1, (now - lastTime) / 1000);
  lastTime = now;
  accumulator += elapsed;
  let steps = 0;
  while (accumulator >= STEP && steps < 8) {
    update(STEP);
    accumulator -= STEP;
    steps += 1;
  }
  if (steps === 0) {
    // still keep animations alive on very high refresh displays
    update(Math.min(STEP, elapsed));
  }
  render(ctx, G);
  requestAnimationFrame(frame);
}

// ---------------------------------------------------------------------------
// Input
// ---------------------------------------------------------------------------

function pressJump() {
  input.jump = true;
  input.jumpPressed = true;
  sound.ensure();
}

function releaseJump() {
  input.jump = false;
}

function pressRun() {
  input.run = true;
  input.runPressed = true;
  sound.ensure();
}

function releaseRun() {
  input.run = false;
}

function togglePause() {
  if (G.state === 'play') {
    G.state = 'pause';
    sound.stopMusic();
  } else if (G.state === 'pause') {
    G.state = 'play';
    input.jumpPressed = input.runPressed = false;
    sound.startMusic();
  }
}

function toggleMute() {
  sound.ensure();
  sound.setMuted(!sound.muted);
  soundBtn.classList.toggle('muted', sound.muted);
}

const KEY_LEFT = new Set(['ArrowLeft', 'KeyA']);
const KEY_RIGHT = new Set(['ArrowRight', 'KeyD']);
const KEY_JUMP = new Set(['Space', 'KeyZ', 'KeyW', 'ArrowUp']);
const KEY_RUN = new Set(['ShiftLeft', 'ShiftRight', 'KeyX']);

window.addEventListener('keydown', (event) => {
  const code = event.code;
  if (KEY_LEFT.has(code)) { input.left = true; event.preventDefault(); }
  else if (KEY_RIGHT.has(code)) { input.right = true; event.preventDefault(); }
  else if (KEY_JUMP.has(code)) {
    if (!event.repeat) pressJump();
    event.preventDefault();
  } else if (KEY_RUN.has(code)) {
    if (!event.repeat) pressRun();
    event.preventDefault();
  } else if (code === 'KeyP' || code === 'Escape') {
    togglePause();
    event.preventDefault();
  } else if (code === 'KeyM') {
    toggleMute();
  } else if (code === 'Enter') {
    if (G.state === 'title' || G.state === 'over') startGame();
  }

  if (G.state === 'title' && (KEY_JUMP.has(code) || code === 'Enter')) startGame();
}, { passive: false });

window.addEventListener('keyup', (event) => {
  const code = event.code;
  if (KEY_LEFT.has(code)) input.left = false;
  else if (KEY_RIGHT.has(code)) input.right = false;
  else if (KEY_JUMP.has(code)) releaseJump();
  else if (KEY_RUN.has(code)) releaseRun();
});

window.addEventListener('blur', () => {
  input.left = input.right = input.jump = input.run = false;
  if (G.state === 'play') togglePause();
});

document.addEventListener('visibilitychange', () => {
  if (document.hidden && G.state === 'play') togglePause();
});

// touch controls
for (const button of touch.querySelectorAll('button[data-key]')) {
  const key = button.dataset.key;
  const down = (event) => {
    event.preventDefault();
    button.classList.add('pressed');
    if (button.setPointerCapture) {
      try { button.setPointerCapture(event.pointerId); } catch { /* ignore */ }
    }
    if (key === 'left') input.left = true;
    else if (key === 'right') input.right = true;
    else if (key === 'jump') pressJump();
    else if (key === 'run') pressRun();
  };
  const up = (event) => {
    event.preventDefault();
    button.classList.remove('pressed');
    if (key === 'left') input.left = false;
    else if (key === 'right') input.right = false;
    else if (key === 'jump') releaseJump();
    else if (key === 'run') releaseRun();
  };
  button.addEventListener('pointerdown', down);
  button.addEventListener('pointerup', up);
  button.addEventListener('pointercancel', up);
  button.addEventListener('lostpointercapture', up);
  button.addEventListener('contextmenu', (e) => e.preventDefault());
}

// swipe-free tap on the canvas jumps when playing on touch devices
canvas.addEventListener('pointerdown', (event) => {
  if (event.pointerType === 'mouse') return;
  if (G.state === 'play') pressJump();
  else if (G.state === 'title') startGame();
});
canvas.addEventListener('pointerup', (event) => {
  if (event.pointerType === 'mouse') return;
  releaseJump();
});

overlay.addEventListener('click', (event) => {
  if (event.target.closest('button')) startGame();
});

soundBtn.addEventListener('click', toggleMute);
pauseBtn.addEventListener('click', () => {
  if (G.state === 'title') return;
  togglePause();
});

// ---------------------------------------------------------------------------
// Boot
// ---------------------------------------------------------------------------

resetLevel();
G.state = 'title';
requestAnimationFrame((now) => {
  lastTime = now;
  requestAnimationFrame(frame);
});

