export function drawGoomba(ctx, x, y, w, h, o) {
  const facing = o.vx < 0 ? -1 : 1;
  ctx.save();
  ctx.translate(Math.round(x + w / 2), Math.round(y + h));
  ctx.scale(facing, 1);

  if (o.state === 'squash') {
    px(ctx, -7, -5, 14, 5, '#8b4a1f');
    px(ctx, -7, -5, 14, 1, '#a9622c');
    px(ctx, -6, -2, 3, 2, '#3a1f0c');
    px(ctx, 3, -2, 3, 2, '#3a1f0c');
    ctx.restore();
    return;
  }

  const step = Math.floor(o.anim * 8) % 2;
  // feet
  px(ctx, -7 + step, -3, 6, 3, '#3a1f0c');
  px(ctx, 1 - step, -3, 6, 3, '#3a1f0c');
  // body
  px(ctx, -6, -12, 12, 9, '#8b4a1f');
  px(ctx, -7, -9, 14, 6, '#8b4a1f');
  px(ctx, -5, -13, 10, 2, '#a9622c');
  px(ctx, -6, -12, 12, 1, '#a9622c');
  px(ctx, -5, -4, 10, 1, '#6d3615');
  // eyes
  px(ctx, -5, -10, 4, 4, WHITE);
  px(ctx, 1, -10, 4, 4, WHITE);
  px(ctx, -2, -9, 2, 3, DARK);
  px(ctx, 2, -9, 2, 3, DARK);
  // angry brows
  px(ctx, -6, -12, 4, 1, '#4a250e');
  px(ctx, 2, -12, 4, 1, '#4a250e');
  px(ctx, -5, -11, 2, 1, '#4a250e');
  px(ctx, 3, -11, 2, 1, '#4a250e');
  // mouth
  px(ctx, -2, -6, 4, 1, '#4a250e');
  ctx.restore();
}

content.text:
Good. Now CSS updates:
- #brand styles
- body dot grid
- #touch column layout + deck-hint + touch-row
- landscape overrides for .touch-row.

Let me edit styles.css.

Current #touch:
```css
#touch {
  display: none;
  flex: 0 0 auto;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  padding: ...;
  height: var(--controls-h);
  ...
}
.pad { display:flex; align-items:center; gap:10px; }
```
Change #touch to flex-direction: column; justify-content: flex-end; gap: 10px; align-items: stretch.
Add .touch-row { display:flex; justify-content:space-between; align-items:flex-end; gap:12px; width:100%; }
.deck-hint { margin:0; text-align:center; font-size:11px; letter-spacing:.08em; color:#8fa4cf; text-transform:uppercase; font-weight:700; }
.deck-hint b { color:#ffd34d; }

Landscape: #touch { flex-direction: row? } Actually in landscape overlay we want only the pads row full width. Set .deck-hint { display:none } in landscape; #touch .touch-row { width:100% }.

Brand CSS:
```css
#brand { display:none; }
@media (pointer: coarse) and (orientation: portrait) {
  #brand { display:flex; flex-direction:column; align-items:center; line-height:.84; padding-top: calc(8px + var(--safe-t)); flex:0 0 auto; }
  .brand-super { font-size:10px; letter-spacing:.4em; text-transform:uppercase; color:#ffd34d; font-weight:800; text-shadow:0 2px 6px rgba(0,0,0,.6); }
  .brand-mario { font-size:26px; line-height:1; font-weight:900; text-transform:uppercase; color:#ff3a2e; -webkit-text-stroke:1.5px #7d100b; paint-order:stroke fill; text-shadow:0 3px 0 #7d100b, 0 8px 16px rgba(0,0,0,.5); }
}
```
Also on portrait, adjust --controls-h maybe.

Dot grid on body::before.

Let me apply.

