import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');

const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(400);
await page.click('#startBtn');
await page.waitForTimeout(500);
await page.screenshot({ path: join(out, 'v2-start.png') });

// move a little and jump
await page.keyboard.down('ArrowRight');
await page.waitForTimeout(1400);
await page.keyboard.down('Space');
await page.waitForTimeout(220);
await page.keyboard.up('Space');
await page.waitForTimeout(700);
await page.screenshot({ path: join(out, 'v2-run.png') });
await page.keyboard.up('ArrowRight');

// teleport near pipes / goombas
await page.evaluate(() => {
  const G = window.__G;
  G.player.x = 36 * 16;
  G.player.y = 13 * 16 - G.player.h;
  G.player.vx = 0; G.player.vy = 0;
  G.cam.x = G.player.x - 160;
});
await page.waitForTimeout(600);
await page.screenshot({ path: join(out, 'v2-pipes.png') });

// teleport near the flag
await page.evaluate(() => {
  const G = window.__G;
  G.player.x = 185 * 16;
  G.player.y = 13 * 16 - G.player.h;
  G.player.vx = 0; G.player.vy = 0;
  G.cam.x = G.player.x - 120;
});
await page.waitForTimeout(600);
await page.screenshot({ path: join(out, 'v2-flag.png') });

// grab a mushroom by spawning one and collecting it
await page.evaluate(() => {
  const G = window.__G;
  G.items.push({ type: 'mushroom', x: G.player.x + 30, y: G.player.y, w: 14, h: 14, vx: 0, vy: 0, emerge: 0, onGround: false, remove: false });
});
await page.keyboard.down('ArrowRight');
await page.waitForTimeout(600);
await page.keyboard.up('ArrowRight');
await page.waitForTimeout(300);
const st = await page.evaluate(() => {
  const G = window.__G;
  return { power: G.player.power, h: G.player.h, score: G.score, state: G.state };
});
await page.screenshot({ path: join(out, 'v2-big.png') });
console.log('state', st, 'errors', errors);
await browser.close();

