import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');

const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(300);
await page.click('#startBtn');
await page.waitForTimeout(300);

const snap = () => page.evaluate(() => {
  const G = window.__G;
  const p = G.player;
  const l = G.level;
  const tile = (x, y) => l.tiles[y * l.W + x];
  return {
    state: G.state, x: Math.round(p.x), y: Math.round(p.y), h: p.h, power: p.power,
    vx: Math.round(p.vx), vy: Math.round(p.vy), onGround: p.onGround,
    score: G.score, coins: G.coinCount, lives: G.lives,
    tile16: tile(16, 9), tile23: tile(23, 9), items: G.items.map((i) => i.type),
    enemies: G.enemies.filter((e) => !e.remove).map((e) => `${e.type}:${e.state}:${Math.round(e.x)}`),
  };
});

// --- bump a coin block -----------------------------------------------------
await page.evaluate(() => {
  const G = window.__G;
  G.player.x = 16 * 16 + 2;
  G.player.y = 13 * 16 - G.player.h;
  G.player.vx = 0; G.player.vy = 0;
  G.cam.x = 100;
});
await page.waitForTimeout(250);
console.log('before block', await snap());
await page.keyboard.down('Space');
await page.waitForTimeout(160);
await page.keyboard.up('Space');
await page.waitForTimeout(600);
console.log('after block', await snap());

// --- bump a power block and grab mushroom ---------------------------------
await page.evaluate(() => {
  const G = window.__G;
  G.player.x = 23 * 16 + 2;
  G.player.y = 13 * 16 - G.player.h;
  G.player.vx = 0; G.player.vy = 0;
  G.cam.x = 240;
});
await page.waitForTimeout(250);
await page.keyboard.down('Space');
await page.waitForTimeout(160);
await page.keyboard.up('Space');
await page.waitForTimeout(900);
console.log('after power block', await snap());
// walk to mushroom
await page.keyboard.down('ArrowRight');
await page.waitForTimeout(1200);
await page.keyboard.up('ArrowRight');
await page.waitForTimeout(300);
console.log('after mushroom', await snap());
await page.screenshot({ path: join(out, 'v5-big-mario.png') });

// --- stomp a goomba -------------------------------------------------------
await page.evaluate(() => {
  const G = window.__G;
  const g = G.enemies.find((e) => e.type === 'goomba' && !e.remove && e.awake);
  if (g) {
    G.player.x = g.x;
    G.player.y = g.y - 40;
    G.player.vy = 100;
    G.cam.x = g.x - 150;
  }
});
await page.waitForTimeout(700);
console.log('after stomp', await snap());

// --- pause / resume -------------------------------------------------------
await page.keyboard.press('KeyP');
await page.waitForTimeout(200);
console.log('paused', await page.evaluate(() => window.__G.state));
await page.screenshot({ path: join(out, 'v5-pause.png') });
await page.keyboard.press('KeyP');
await page.waitForTimeout(200);
console.log('resumed', await page.evaluate(() => window.__G.state));

// --- die in a pit ---------------------------------------------------------
await page.evaluate(() => {
  const G = window.__G;
  G.player.x = 69 * 16 + 8;
  G.player.y = 12 * 16;
  G.player.vy = 0;
  G.cam.x = 1000;
});
await page.waitForTimeout(300);
console.log('pit', await page.evaluate(() => ({ state: window.__G.state, lives: window.__G.lives })));
await page.waitForTimeout(2600);
console.log('respawn', await page.evaluate(() => ({ state: window.__G.state, lives: window.__G.lives, x: Math.round(window.__G.player.x) })));

console.log('errors', errors);
await browser.close();

