import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');

const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(300);
await page.click('#startBtn');
await page.waitForTimeout(300);
await page.evaluate(() => { window.__G.lives = 99; });

await page.keyboard.down('ArrowRight');
await page.keyboard.down('ShiftLeft');

let jumping = false;
let lastX = 0;
let stuck = 0;
let lastLog = 0;
const start = Date.now();

for (let i = 0; i < 900; i++) {
  const info = await page.evaluate(() => {
    const G = window.__G, p = G.player, l = G.level;
    const tx = Math.floor((p.x + p.w) / 16);
    const ty = Math.floor((p.y + p.h - 1) / 16);
    const solidAt = (x, y) => (x < 0 || x >= l.W ? true : y >= l.H ? false : l.solid[y * l.W + x] === 1);
    const gapAhead = !solidAt(tx + 1, ty + 1) && !solidAt(tx + 2, ty + 1);
    const wallAhead = solidAt(tx + 1, ty) || solidAt(tx + 1, ty - 1);
    const enemyAhead = G.enemies.some((e) => !e.remove && e.type !== 'piranha' && e.x > p.x && e.x - p.x < 60 && Math.abs(e.y - p.y) < 34);
    const plantAhead = G.enemies.some((e) => e.type === 'piranha' && e.plantH > 4 && Math.abs(e.x - p.x) < 46);
    return { state: G.state, x: p.x, y: p.y, onGround: p.onGround, gapAhead, wallAhead, enemyAhead, plantAhead, score: G.score, lives: G.lives, power: p.power };
  });
  if (info.state === 'over' || info.state === 'clear') { console.log('ended', info); break; }

  if (info.state === 'play') {
    if (Math.abs(info.x - lastX) < 0.6) stuck++; else stuck = 0;
    lastX = info.x;
    const wantJump = info.onGround && (info.gapAhead || info.wallAhead || info.enemyAhead || info.plantAhead || stuck > 20);
    if (wantJump && !jumping) {
      jumping = true;
      await page.keyboard.down('Space');
      setTimeout(() => {}, 0);
      await page.waitForTimeout(200);
      await page.keyboard.up('Space');
      jumping = false;
    }
  }
  if (i % 20 === 0 && Date.now() - lastLog > 2000) {
    lastLog = Date.now();
    console.log(Math.round((Date.now() - start) / 1000) + 's', { state: info.state, x: Math.round(info.x), y: Math.round(info.y), score: info.score, lives: info.lives, power: info.power });
  }
  await page.waitForTimeout(70);
}
await page.keyboard.up('ArrowRight');
await page.keyboard.up('ShiftLeft');
const fin = await page.evaluate(() => ({ state: window.__G.state, x: Math.round(window.__G.player.x), score: window.__G.score, lives: window.__G.lives, coins: window.__G.coinCount }));
console.log('final', fin, 'errors', errors);
await page.screenshot({ path: join(out, 'bot2-final.png') });
await browser.close();

