import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');

const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
const errors = [];

async function shoot(width, height, name, opts = {}) {
  const page = await browser.newPage({ viewport: { width, height }, isMobile: !!opts.mobile, hasTouch: !!opts.mobile, deviceScaleFactor: opts.dpr || 1 });
  page.on('pageerror', (e) => errors.push(`${name} pageerror: ` + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(`${name} console: ` + m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(400);
  await page.screenshot({ path: join(out, `${name}-title.png`) });
  await page.click('#startBtn');
  await page.waitForTimeout(500);
  await page.screenshot({ path: join(out, `${name}-play.png`) });
  return page;
}

const d = await shoot(1440, 900, 'v4-desktop');
// move right, jump onto blocks area
await d.keyboard.down('ArrowRight');
await d.waitForTimeout(1500);
await d.keyboard.down('Space');
await d.waitForTimeout(250);
await d.keyboard.up('Space');
await d.waitForTimeout(500);
await d.screenshot({ path: join(out, 'v4-desktop-jump.png') });
await d.keyboard.up('ArrowRight');
await d.close();

const m = await shoot(390, 844, 'v4-mobile', { mobile: true, dpr: 2 });
await m.close();

const l = await shoot(844, 390, 'v4-landscape', { mobile: true, dpr: 2 });
await l.close();

console.log('errors', errors);
await browser.close();

