function isSolid(tx, ty) {
  const level = G.level;
  if (tx < 0 || tx >= level.W) return true;
  if (ty < 0) return false;
  if (ty >= level.H) return false;
  return level.solid[ty * level.W + tx] === 1;
}

function moveX(e, dt, stopOnHit = true) {
  e.hitWall = false;
